ASK,KAAT,CAAcX,IAAd,CAAoBC,IAApB,CAA0BJ,SAA1B,CAAqC,CACnC,MAAO,IAAID,KAAJ,CAASC,SAAT,EAAoBQ,eAApB,CAAoCL,IAApC,CAA0CC,IAA1C,CACR,CACD,MAAOU,KACR,CAvJqB,EAAtB","file":"learn.js","sourcesContent":["/** @jsx h */\n'use strict';\nconst {h, Component, render} = window.preact;\n\n// Incorrectly configured build doesn't replace in-place process.env:\n// ensure the js still works\nvar process = process || {};\nprocess.env = process.env || {};\n\nwindow.MEMLIKE = window.MEMLIKE || {};\nwindow.MEMLIKE.js_learn = {\n  build_date: "2026-05-13T04:56-04:00",\n};\n\n/* global $, window, document, console */\n/* global setTimeout, setInterval, clearInterval, localStorage, Set */\n$(document).ready(function(){\n  Object.freeze(window.MEMLIKE.course);\n  Object.freeze(window.MEMLIKE.garden);\n\n  window.MEMLIKE.sessionSettings = {\n    'disable_multimedia': !!localStorage.getItem('sessionSettings_disable_multimedia'), // disable_multimedia is actually a setting in memrise\n    'disable_tapping': !!localStorage.getItem('sessionSettings_disable_tapping'),\n    'disable_typing': !!localStorage.getItem('sessionSettings_disable_typing'),\n    'enable_audio_autoplay': localStorage.getItem('sessionSettings_enable_audio_autoplay'),\n    'strict_punctuation': !!localStorage.getItem('sessionSettings_strict_punctuation'),\n    'strict_case': !!localStorage.getItem('sessionSettings_strict_case'),\n    'save_progress': !!window.MEMLIKE.garden.session_settings_save_progress,\n    'reverse_prompt_and_answer': !!window.MEMLIKE.garden.session_settings_reverse_prompt_and_answer,\n    'session_id': window.MEMLIKE.garden.session_id,\n  };\n  if (window.MEMLIKE.sessionSettings.enable_audio_autoplay === null) {\n    window.MEMLIKE.sessionSettings.enable_audio_autoplay = true;\n  }\n  render(<Learn\n    level_index={window.MEMLIKE.garden.level_index}\n    session_type={window.MEMLIKE.garden.session_type}\n    preview_thing_id={window.MEMLIKE.garden.preview_thing_id}\n    session_id={window.MEMLIKE.garden.session_is_anonymous}\n    course={window.MEMLIKE.course}\n  />, document.getElementById('learn-container'));\n\n  render(<LearnSettingsBtn\n    session_type={window.MEMLIKE.garden.session_type}\n  />, document.getElementById('learn-settings-btn'));\n});\n\n//+--------------------------------------------------------\n//| Helper functions\n//+--------------------------------------------------------\n\n/**\n * Returns a random element from the current array\n */\n$.fn.random = function() {\n  var randomIndex = Math.floor(Math.random() * this.length);\n  return $(this[randomIndex]);\n};\nArray.prototype.random = function(){\n  var randomIndex = Math.floor(Math.random() * this.length);\n  return this[randomIndex];\n};\n\n/**\n* Returns an integer random number between min (included) and max (included)\n* @param int min\n* @param int max\n* @return int\n*/\nfunction randrange(min, max) {\n  return Math.floor(Math.random() * (max - min + 1)) + min;\n}\n\n/**\n * Returns a new array, containing the elements of arr shuffled\n * @param array arr\n * @return array\n */\nfunction randomize(arr){\n var c = arr.length, rnd;\n\n while(c){\n  rnd = (Math.random() * c--) | 0;\n  [arr[c], arr[rnd]] = [arr[rnd], arr[c]];\n }\n return arr;\n}\n\n/**\n * Returns the character corresponding to the keycode\n * @param int key\n * @return string char\n */\nfunction fromKeyCode(key) {\n  return String.fromCharCode((96 <= key && key <= 105)? key-48 : key);\n}\n\n/**\n * Create a Date object from a valid ISO 8601 string\n * @param string value\n * @return Date\n */\nfunction decodeDateString(value) {\n  if (!value) {\n    return null;\n  }\n  if (value instanceof Date) {\n    return value;\n  }\n  var d = new Date(value);\n\n  // invalid value: use now\n  if (isNaN(d.getTime())) {\n    return new Date();\n  }\n  return d;\n}\n\n//+--------------------------------------------------------\n//| Settings\n//+--------------------------------------------------------\n\nclass LearnSettingsModal extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {...window.MEMLIKE.sessionSettings};\n\n    this.onCloseModal = this.onCloseModal.bind(this);\n    this.onUpdateSettings = this.onUpdateSettings.bind(this);\n  }\n\n  onCloseModal() {\n    window.modal.close();\n  }\n\n  onUpdateSettings() {\n    Object.assign(window.MEMLIKE.sessionSettings, this.state);\n    localStorage.setItem('sessionSettings_disable_multimedia', this.state.disable_multimedia ? '1' : '');\n    localStorage.setItem('sessionSettings_disable_tapping', this.state.disable_tapping ? '1' : '');\n    localStorage.setItem('sessionSettings_disable_typing', this.state.disable_typing ? '1' : '');\n    localStorage.setItem('sessionSettings_enable_audio_autoplay', this.state.enable_audio_autoplay ? '1' : '');\n    localStorage.setItem('sessionSettings_strict_punctuation', this.state.strict_punctuation ? '1' : '');\n    localStorage.setItem('sessionSettings_strict_case', this.state.strict_case ? '1' : '');\n    localStorage.setItem('sessionSettings_id', this.state.session_id || '');\n\n    this.onCloseModal();\n    window.GlobalEventEmitter.dispatch('update-settings', this.state);\n  }\n\n  handleChange(key) {\n    this.setState({\n      [key]: !this.state[key],\n    });\n  }\n\n  render() {\n    return <div className=\"vcenter settings learn-settings\">\n      <div className=\"form\">\n        <fieldset>\n          <div>\n            <input\n              id=\"disable_typing\"\n              type=\"checkbox\"\n              defaultChecked={this.state.disable_typing}\n              onChange={this.handleChange.bind(this, 'disable_typing')}\n              autoComplete=\"off\"\n            />\n            <label htmlFor=\"disable_typing\">{window.I18N['learn_settings_disable_typing']}</label>\n          </div>\n          <div>\n            <input\n              id=\"disable_tapping\"\n              type=\"checkbox\"\n              defaultChecked={this.state.disable_tapping}\n              onChange={this.handleChange.bind(this, 'disable_tapping')}\n              autoComplete=\"off\"\n            />\n            <label htmlFor=\"disable_tapping\">{window.I18N['learn_settings_disable_tapping']}</label>\n          </div>\n          <div>\n            <input\n              id=\"disable_multimedia\"\n              type=\"checkbox\"\n              defaultChecked={this.state.disable_multimedia}\n              onChange={this.handleChange.bind(this, 'disable_multimedia')}\n              autoComplete=\"off\"\n            />\n            <label htmlFor=\"disable_multimedia\">{window.I18N['learn_settings_disable_multimedia']}</label>\n          </div>\n          <div>\n            <input\n              id=\"enable_audio_autoplay\"\n              type=\"checkbox\"\n              defaultChecked={this.state.enable_audio_autoplay}\n              onChange={this.handleChange.bind(this, 'enable_audio_autoplay')}\n              autoComplete=\"off\"\n            />\n            <label htmlFor=\"enable_audio_autoplay\">{window.I18N['learn_settings_enable_audio_autoplay']}</label>\n          </div>\n        </fieldset>\n        <fieldset>\n          <div>\n            <input\n              id=\"reverse_prompt_and_answer\"\n              type=\"checkbox\"\n              defaultChecked={this.state.reverse_prompt_and_answer}\n              onChange={this.handleChange.bind(this, 'reverse_prompt_and_answer')}\n              autoComplete=\"off\"\n            />\n            <label htmlFor=\"reverse_prompt_and_answer\">{window.I18N['learn_settings_reverse_prompt_and_answer']}</label>\n          </div>\n          <div>\n            <input\n              id=\"strict_punctuation\"\n              type=\"checkbox\"\n              defaultChecked={this.state.strict_punctuation}\n              onChange={this.handleChange.bind(this, 'strict_punctuation')}\n              autoComplete=\"off\"\n            />\n            <label htmlFor=\"strict_punctuation\">{window.I18N['learn_settings_strict_punctuation']}</label>\n          </div>\n          <div>\n            <input\n              id=\"strict_case\"\n              type=\"checkbox\"\n              defaultChecked={this.state.strict_case}\n              onChange={this.handleChange.bind(this, 'strict_case')}\n              autoComplete=\"off\"\n            />\n            <label htmlFor=\"strict_case\">{window.I18N['learn_settings_strict_case']}</label>\n          </div>\n        </fieldset>\n        <fieldset>\n          <div>\n            <input\n              id=\"save_progress\"\n              type=\"checkbox\"\n              defaultChecked={this.state.save_progress}\n              onChange={this.handleChange.bind(this, 'save_progress')}\n              autoComplete=\"off\"\n            />\n            <label htmlFor=\"save_progress\">{window.I18N['learn_settings_save_progress']}</label>\n          </div>\n        </fieldset>\n      </div>\n      <div className=\"btn-group\">\n        <button className=\"btn\" onClick={this.onCloseModal} autoFocus={true}>{window.I18N['cancel']}</button>\n        <button className=\"btn green\" onClick={this.onUpdateSettings}>{window.I18N['save']}</button>\n      </div>\n    </div>\n  }\n}\n\nclass LearnSettingsBtn extends Component {\n  constructor(props) {\n    super(props);\n\n    this.show = false;\n    this.onToggleSettings = this.onToggleSettings.bind(this);\n    this.onCloseModal = this.onCloseModal.bind(this);\n  }\n  onCloseModal() {\n    window.modal.onClose('learn-settings', null);\n    if(!this.show) {\n      return;\n    }\n    this.show = false;\n    Timer && Timer.continue();\n  }\n  onToggleSettings() {\n    this.show = !this.show;\n    if(!this.show) {\n      return;\n    }\n    Timer && Timer.pause();\n\n    // Render LearnSettingsModal and put it in our modal\n    var div = window.modal.getContainer().get(0).querySelector('.modal');\n    div.innerHTML = '';\n    render(<LearnSettingsModal />, div);\n\n    window.modal.reopen();\n    window.modal.onClose('learn-settings', this.onCloseModal);\n\n    setTimeout(function(){\n      $('button[autofocus]', div).first().focus();\n    }, 0);\n  }\n  render() {\n    if (this.props.session_type == 'preview') {\n      return null;\n    }\n    return (\n      <button className=\"settings-btn\" type=\"button\" onClick={this.onToggleSettings} title={window.I18N.learn_settings}>\n        <span className=\"ico ico-settings ico-l ico-grey\"></span>\n      </button>\n    );\n  }\n}\n\n//+--------------------------------------------------------\n//| Speed review timer\n//+--------------------------------------------------------\n\nconst Timer = {\n  maxTime: 6e3,\n  remainingTime: null,\n  lastUpdate: null,\n  target: null,\n  interval: null,\n  callback: null,\n  isRunning: false,\n  isPaused: false,\n\n  stop: function(){\n    Timer.interval && clearInterval(Timer.interval);\n\n    if(!Timer.isRunning) {\n      return;\n    }\n    var time = Date.now();\n\n    // The user submitter an answer: tick a last time\n    Timer.isRunning     = false;\n    Timer.remainingTime -= (time - Timer.lastUpdate);\n    Timer.lastUpdate     = time;\n  },\n  start: function(callback){\n    Timer.callback      = callback;\n    Timer.remainingTime = Timer.maxTime;\n    Timer.lastUpdate    = Date.now();\n    Timer.interval      = setInterval(Timer.tick.bind(this), 150);\n    Timer.isRunning     = true;\n    Timer.isPaused      = false;\n  },\n  getTime: function(){\n    if (Timer.remainingTime === null) {\n      return 0;\n    }\n    return Timer.maxTime - Math.max(Timer.remainingTime, 0);\n  },\n  pause: function() {\n    if (Timer.isPaused) {\n      return;\n    }\n    Timer.isPaused = true;\n  },\n  continue: function() {\n    if (!Timer.isPaused) {\n      return;\n    }\n    Timer.lastUpdate = Date.now();\n    Timer.isPaused = false;\n  },\n  tick: function(){\n    if(!Timer.isRunning || Timer.isPaused) {\n      return;\n    }\n    var time = Date.now();\n    Timer.remainingTime -= (time - Timer.lastUpdate);\n    Timer.lastUpdate     = time;\n\n    if(Timer.remainingTime <= 0) {\n      clearInterval(Timer.interval);\n      Timer.isRunning = false;\n\n      $('#speed_review-timer').css('height', '100%');\n\n      Timer.callback && setTimeout(Timer.callback, 300);\n    } else {\n      var percent = 1 - (Timer.remainingTime / Timer.maxTime);\n      $('#speed_review-timer').css('height', (percent * 100) + '%');\n    }\n  }\n};\n\n//+--------------------------------------------------------\n//| BUILDING STATE.DATA\n//+--------------------------------------------------------\n\nconst LEARN_UNTIL_GROWTH_LEVEL = 6;\nconst LEARN_LASTDATE_TIMEOUT_SECONDS = 172800; // 2 * 24 * 3600 = 2 days ago\nconst LEARN_BUILD_CHOICES_LENGTH = 12;\n\nconst TEST_DIFFICULTY = {\n  'Unknown': 0,\n  'Easy': 1,\n  'Moderate': 2,\n  'Hard': 3,\n};\n\nconst REVIEW_INTERVAL_LADDER = [\n  {interval: .1666, tolerance: .1},\n  {interval: .5, tolerance: .3},\n  {interval: 1, tolerance: .5},\n  {interval: 6, tolerance: 1},\n  {interval: 12, tolerance: 0},\n  {interval: 24, tolerance: 0},\n  {interval: 48, tolerance: 0},\n  {interval: 96, tolerance: 0},\n  {interval: 180, tolerance: 0},\n];\n\n/**\n * Build the session state\n * from the retrieved list of elements to learn\n */\nconst GameDataBuilder = {\n  learnablesMap: {},\n  sessionType: 'preview',\n\n  shouldDisplayPresentation: function(learnableProgress) {\n    if (!learnableProgress || !learnableProgress.last_date) {\n      return true;\n    }\n    try {\n      const lastDate = new Date(learnableProgress.last_date);\n      const thresholdDate = new Date(Date.now() - LEARN_LASTDATE_TIMEOUT_SECONDS * 1000);\n      return lastDate < thresholdDate;\n    } catch(e) {\n      console.error(e);\n      return true;\n    }\n  },\n\n  getScreenList: function(sessionType, learnables, progressMap) {\n    var screens = [];\n\n    switch(sessionType) {\n      case 'learn':\n        let testsToAdd = [];\n\n        for (let learnable of learnables) {\n          const learnableID = '' + learnable.id;\n          const learnableProgress = progressMap[learnableID];\n\n          if (GameDataBuilder.shouldDisplayPresentation(learnableProgress)) {\n            screens.push({\n              learnableID,\n              template: 'presentation',\n              learningGrowthLevel: 0,\n            });\n          }\n\n          // How many times do we have to repeat the test to learn it\n          const growthLevel = learnableProgress ? learnableProgress.growth_level : 0;\n\n          const learningLevel = (growthLevel | 0) + 1;\n          const targetLevel = Math.min((growthLevel | 0) + 3, LEARN_UNTIL_GROWTH_LEVEL);\n\n          if (learningLevel > targetLevel) {\n            console.warn('The following learnable has already been learned:', learnable);\n          } else {\n            testsToAdd.push({learnableID, learningLevel, targetLevel});\n          }\n        }\n\n        // While there are still tests to add\n        while(testsToAdd.length) {\n          let testsToAdd_next = [];\n\n          // For each learnable that have to be tested\n          for(let i = 0; i < testsToAdd.length; i++) {\n            let item = testsToAdd[i];\n            let {learnableID, learningLevel, targetLevel} = item;\n\n            // Get a random index to insert the test\n            // 2 steps after the presentation of the learnable\n            // or anywhere after the first test\n            let idx = screens.findLastIndex((screen) => screen.learnableID == learnableID);\n            let min = 0;\n            let max = screens.length;\n            let isPresentation = false;\n\n            if (idx != -1) {\n              min = idx;\n              isPresentation = idx in screens && screens[idx].template == 'presentation';\n            }\n            let insertAtIndex = isPresentation ? Math.min(min + 2, max) : randrange(min, max);\n\n            // Insert the test at the chosen random index\n            screens.splice(insertAtIndex, 0, {\n              learnableID,\n              template: 'sentinel',\n              learningGrowthLevel: learningLevel, // target growth level\n            });\n\n            // Do we still have to repeat the test to learn it\n            learningLevel += 1;\n            if (targetLevel >= learningLevel) {\n              testsToAdd_next.push({learnableID, learningLevel, targetLevel});\n            }\n          }\n          testsToAdd = testsToAdd_next;\n        }\n        break;\n\n      case 'speed_review':\n      case 'classic_review':\n        for (let learnable of learnables) {\n          screens.push({\n            learnableID: '' + learnable.id,\n            template: 'sentinel',\n            learningGrowthLevel: 0,\n          });\n        }\n        screens = randomize(screens);\n        break;\n\n      case 'preview':\n      default:\n        for (let learnable of learnables) {\n          screens.push({\n            learnableID: '' + learnable.id,\n            template: 'presentation',\n            learningGrowthLevel: 0,\n          });\n        }\n        break;\n    }\n    return screens;\n  },\n\n  /**\n   * Build the \"data\" to store in the current state\n   * from the data retrieved from the backend\n   *\n   * @param string sessionType\n   * @param dict data\n   * @return dict\n   */\n  buildData: function(sessionType, data) {\n\n    // Build screensTemplateMap (data.screensTemplateMap[learnableID][tpl])\n    const screensTemplateMap = {};\n    const learnablesMap = {};\n\n    for (let learnable of data.learnables) {\n      let screens = {};\n      let learnableID = learnable.id.toString();\n\n      // A screen = {correct, is_strict, ...} (cf learning_session_preview.json)\n      for (let screenID in learnable.screens) {\n        let screen = learnable.screens[screenID];\n\n        screens[screen.template] = Object.assign(screen, {learnableID});\n      }\n      screensTemplateMap[learnableID] = screens;\n      learnablesMap[learnableID] = learnable;\n    }\n\n    // Build progressMap {learnableID: {growth_level, current_streak, correct, attempts, is_difficult}}\n    const progressMap = {};\n    for (let item of data.progress) {\n      progressMap['' + item.learnable_id] = Object.assign(item, {\n        created_date: decodeDateString(item.created_date),\n        next_date: decodeDateString(item.next_date),\n        last_date: decodeDateString(item.last_date),\n      });\n    }\n\n    const screens = GameDataBuilder.getScreenList(sessionType, data.learnables, progressMap);\n    console.log('Screens:', screens);\n\n    GameDataBuilder.sessionType = sessionType;\n    GameDataBuilder.learnablesMap = learnablesMap;\n    GameScreenBuilder.reset();\n\n    return {\n      screens,\n      screensTemplateMap,\n      progressMap,\n      learnablesMap,\n    }\n  }\n}\n\n/**\n * Build new screens to accomodate our session settings\n * (inverted prompt/answer)\n */\nconst GameScreenBuilder = {\n  cachedDefinitions: null,\n\n  reset: function() {\n    GameScreenBuilder.cachedDefinitions = null;\n  },\n\n  getDefinitions: function() {\n    var learnables = Object.values(GameDataBuilder.learnablesMap);\n    var list = [];\n\n    for (let i=0; i<learnables.length; i++) {\n      let learnable = learnables[i];\n      let definition = learnable.screens['1'].definition;\n      let hasTokens = learnable.definition_element_tokens;\n\n      // text\n      /**\n        \"id\": 30664511848706,\n        \"learning_element\": \"die Auswertung\",\n        \"definition_element\": \"l'évaluation\",\n        \"learning_element_tokens\": [\"die\", \"Auswertung\"],\n        \"definition_element_tokens\": [\"l\", \"évaluation\"],\n        \"difficulty\": \"unknown\",\n        \"item_type\": \"word\",\n      */\n      if(hasTokens) {\n        let value = learnable.definition_element;\n        let valueSanitized = sanitizeTyping(value);\n\n        if (valueSanitized) {\n          list.push({value, valueSanitized});\n        }\n        definition.alternatives.forEach((value) => {\n          let s = sanitizeTyping(value);\n\n          if (s && ScoreAnswer.getStringDistance(valueSanitized, s) > 3) {\n            list.push({value, valueSanitized: s});\n          }\n        });\n\n      // others\n      } else {\n        /**\n          \"definition\": {\n            \"label\": \"English\",\n            \"kind\": \"text\",\n            \"value\": \"l'évaluation\",\n            \"alternatives\": [],\n            \"style\": [],\n            \"direction\": \"source\",\n            \"markdown\": false\n          },\n          \"definition\": {\n            \"label\": \"Audio\",\n            \"kind\": \"audio\",\n            \"value\": [{\n              \"normal\": \"https://static.memrise.com/uploads/things/audio/36962605_140810_2048_20.mp3\",\n              \"slow\": null\n            }],\n            \"alternatives\": [],\n            \"style\": [],\n            \"direction\": \"source\",\n            \"markdown\": false\n          },\n          \"definition\": {\n            \"label\": \"Brain\",\n            \"kind\": \"image\",\n            \"value\": [\n              \"https://static.memrise.com/uploads/things/images/39867261_140924_0443_47.jpg\",\n              \"https://static.memrise.com/uploads/things/images/39867261_140924_0444_07.jpg\",\n              \"https://static.memrise.com/uploads/things/images/39867261_140924_0445_10.jpg\"\n            ],\n            \"alternatives\": [],\n            \"style\": [],\n            \"direction\": \"source\",\n            \"markdown\": false\n          },\n        */\n        GameScreenBuilder.flattenValue(definition.value).forEach((value) => {\n          list.push({value});\n        });\n        definition.alternatives.forEach((value) => {\n          list.push({value});\n        });\n      }\n    }\n    return list;\n  },\n\n  getChoices: function(kind, correctChoices) {\n    if (!GameScreenBuilder.cachedDefinitions) {\n      GameScreenBuilder.cachedDefinitions = GameScreenBuilder.getDefinitions();\n    }\n    let choices = [];\n\n    // Retrieve the definition of other learnables\n    var definitions = GameScreenBuilder.cachedDefinitions;\n    console.log('Definitions', definitions, kind);\n\n    if (definitions.length <= 15 || kind != 'text') {\n      choices = randomize(definitions).filter((element) => correctChoices.indexOf(element.value) == -1);\n\n    } else {\n      var value = correctChoices[0],\n          valueSanitized = sanitizeTyping(value),\n          valueTokens = valueSanitized.split(' ').slice(0, 10);\n\n      for (let i=0; i<definitions.length; i++) {\n        let definition = definitions[i];\n        if (!definition.valueSanitized || definition.valueSanitized == valueSanitized) {\n          continue;\n        }\n\n        // Retrieve definitions that are fairly similar in length to our current word\n        let itemTokens = definition.valueSanitized.split(' ');\n        let X = valueTokens.map((token, i) => {\n          return i < itemTokens.length ? Math.abs(token.length - itemTokens[i].length) : 1\n        });\n        let w = 1;\n        let x = X.reduce((i, s) => s + i*(w += .5, w), 0) | 0;\n\n        choices.push(Object.assign({weight: x}, definition));\n      }\n      choices = choices.sort((a, b) => a.weight - b.weight);\n    }\n    return choices.slice(0, LEARN_BUILD_CHOICES_LENGTH).map(item => item.value);\n  },\n\n  getInvertedPromptAndAnswer: function(screen) {\n    var answerKind = screen.answer.kind;\n    var promptKind = getPromptType(screen.prompt);\n\n    return [\n      {[answerKind]: screen.answer},\n      screen.prompt[promptKind],\n    ];\n  },\n\n  /**\n   * Normalize value as a flat array of strings\n   *\n   * \"value\": \"l'évaluation\"\n   * -> [\"l'évaluation\"]\n   *\n   * \"value\": [{\n   *   \"normal\": \"https://static.memrise.com/uploads/things/audio/36962605_140810_2048_20.mp3\",\n   *   \"slow\": null\n   * }],\n   * -> [\"https://static.memrise.com/uploads/things/audio/36962605_140810_2048_20.mp3\"]\n   *\n   * \"value\": [\n   *   \"https://static.memrise.com/uploads/things/images/39867261_140924_0443_47.jpg\",\n   *   \"https://static.memrise.com/uploads/things/images/39867261_140924_0444_07.jpg\",\n   *   \"https://static.memrise.com/uploads/things/images/39867261_140924_0445_10.jpg\"\n   * ]\n   * -> idem\n   */\n  flattenValue: function(value) {\n    const inner = function(value) {\n      if (typeof value == 'string') {\n        return [value];\n      }\n      if (value.normal) {\n        return value.normal;\n      }\n      if (value.forEach && value.length > 0) {\n        return value.map((s) => inner(s));\n      }\n      console.error('Dont know how to flatten this:', value);\n    }\n    return inner(value).flat();\n  },\n\n  buildScreen_reversed_multiple_choice: function(learnableScreens) {\n    if ('reversed_multiple_choice2' in learnableScreens) {\n      return true;\n    }\n    var screen = Object.assign({}, learnableScreens.multiple_choice);\n    screen.template = 'reversed_multiple_choice2';\n    [screen.prompt, screen.answer] = GameScreenBuilder.getInvertedPromptAndAnswer(screen);\n\n    screen.correct = [];\n    let value = GameScreenBuilder.flattenValue(screen.answer.value).forEach((value) => {\n      screen.correct.push(value);\n    });\n    screen.answer.alternatives.forEach((value) => {\n      screen.correct.push(value);\n    });\n\n    screen.choices = GameScreenBuilder.getChoices(\n      screen.answer.kind,\n      screen.correct,\n    );\n    learnableScreens['reversed_multiple_choice2'] = screen;\n    console.log('buildScreen_reversed_multiple_choice', screen, learnableScreens.reversed_multiple_choice);\n    return true;\n  },\n\n  buildScreen_reverse_typing: function(learnableScreens, category) {\n    if ('reversed_typing' in learnableScreens) {\n      return true;\n    }\n    var screen = Object.assign({}, learnableScreens.typing);\n    screen.template = 'reversed_typing';\n    [screen.prompt, screen.answer] = GameScreenBuilder.getInvertedPromptAndAnswer(screen);\n    if (screen.answer.kind != 'text') {\n      return false;\n    }\n    learnableScreens['reversed_typing'] = screen;\n\n    screen.correct = [];\n    GameScreenBuilder.flattenValue(screen.answer.value).forEach((value) => {\n      screen.correct.push(value);\n    });\n    screen.answer.alternatives.forEach((value) => {\n      screen.correct.push(value);\n    });\n\n    // Set tapping letters\n    var letters = sanitizeTyping(screen.answer.value, this.is_strict);\n    var keyboard = new Set(letters.replace(/\\s/g, '').replace(/[a-zA-Z0-9]/g, '').split(''));\n\n    if (keyboard.size < 5 && category && category.keyboard) {\n      var categoryKeyboard = new Set(category.keyboard.split(''));\n\n      var newLetters = randomize(Array.from(categoryKeyboard.difference(keyboard)));\n      newLetters.slice(0, 5 - keyboard.size).forEach((letter) => {\n        keyboard.add(letter);\n      });\n    }\n    screen.choices = randomize(Array.from(keyboard));\n    console.log('buildScreen_reverse_typing', screen);\n    return true;\n  }\n};\n\nconst GameProgressHandler = {\n  events: [],\n  isSaving: false,\n\n  /**\n   * Compute the next growh level for the given progress,\n   * assuming the user gave the right answer\n   *\n   * @param dict learnableProgress\n   * @param int growthLevel\n   */\n  setNextScreenGrowthLevel: function(learnableProgress, difficulty=TEST_DIFFICULTY.Easy) {\n\n    // FirstOnboardingSessionGrowthLevelStrategy\n    if (GameDataBuilder.session_type == 'first_session') {\n      return 2 === learnableProgress.growth_level ? LEARN_UNTIL_GROWTH_LEVEL : learnableProgress.growth_level + 1;\n    }\n\n    // StandardGrowthLevelStrategy\n    if (true) {\n      return learnableProgress.growth_level + 1;\n    }\n\n    // SuperchargeGrowthLevelStrategy\n    return (\n      learnableProgress.attempts === learnableProgress.correct\n      && learnableProgress.growth_level < LEARN_UNTIL_GROWTH_LEVEL\n      && (\n          difficulty == TEST_DIFFICULTY.Easy && learnableProgress.growth_level >= 2\n       || difficulty == TEST_DIFFICULTY.Moderate && learnableProgress.growth_level >= 3\n      )\n    ) ? LEARN_UNTIL_GROWTH_LEVEL : learnableProgress.growth_level + 1;\n  },\n\n  /**\n   * Create a new date, with [interval] days added to date\n   *\n   * @param Date date\n   * @param float interval (in days) - see REVIEW_INTERVAL_LADDER\n   * @return Date\n   */\n  getDateIncrementedByInterval: function(date, interval) {\n    const deltaFrom = 0,\n          deltaTo = .007;\n\n    if (!interval) {\n      interval = deltaTo;\n    }\n    if (!date) {\n      date = new Date();\n    }\n    interval += randrange(deltaFrom, deltaTo);\n\n    return new Date(date.getTime() + 24 * interval * 3600 * 1000);\n  },\n\n  /**\n   * Retrieve the index corresponding\n   * to the given interval in the REVIEW_INTERVAL_LADDER (fuzzy)\n   *\n   * @param float interval\n   * @return int index\n   */\n  getRungIndex: function(interval) {\n\n    // Get the last rung greater than the given interval\n    for (var i = REVIEW_INTERVAL_LADDER.length; i > 0 && REVIEW_INTERVAL_LADDER[--i | 0].interval > interval;) {\n        // pass\n    }\n    // Return the rung no greather than the given interval\n    return Math.max(i - 1, 0);\n  },\n\n  /**\n   * Compute the interval and next_date for the given progress\n   *\n   * @param dict progress\n   * @param Date date_answer\n   * @param float score\n   * @return dict\n   */\n  setNextScreenIntervalDate: function(learnableProgress, dateAnswer, score) {\n\n    // No review data until we learned the item\n    if (learnableProgress.growth_level < LEARN_UNTIL_GROWTH_LEVEL) {\n      return {\n        interval : null,\n        next_date: null,\n      };\n    }\n\n    // We just learned the item: set the next review with the first interval\n    if(!learnableProgress.interval\n      || !learnableProgress.next_date\n      || learnableProgress.interval < REVIEW_INTERVAL_LADDER[0].interval\n    ) {\n      var interval = REVIEW_INTERVAL_LADDER[0].interval;\n      return {\n        interval,\n        next_date: GameProgressHandler.getDateIncrementedByInterval(dateAnswer, interval),\n      }\n    }\n\n    var rungIndex = GameProgressHandler.getRungIndex(learnableProgress.interval),\n        tolerance = REVIEW_INTERVAL_LADDER[rungIndex].tolerance,\n        reviewDate = new Date(learnableProgress.next_date.getTime() - 24 * tolerance * 3600 * 1000),\n        isReviewDatePast = (new Date()).getTime() >= reviewDate.getTime();\n\n    // We got the answer right but the item isn't due to review: keep the nextDate as-is\n    var isCorrect = score == 1,\n        isIncorrect = score == 0;\n\n    if (isCorrect && !isReviewDatePast) {\n      return {\n        interval : learnableProgress.interval,\n        next_date: learnableProgress.next_date,\n      };\n    }\n\n    if (isIncorrect) {\n      rungIndex = rungIndex > 2 ? 2 : rungIndex;\n    } else if(isCorrect) {\n      if(rungIndex === 1\n        && learnableProgress.current_streak === learnableProgress.attempts\n        && learnableProgress.current_streak > 0\n      ) {\n        rungIndex += 2;\n      } else {\n        rungIndex += 1;\n      }\n    } else { // nearly correct\n      rungIndex = learnableProgress.current_streak > 0 ? rungIndex : Math.max(rungIndex - 1, 0);\n    }\n\n    var interval = REVIEW_INTERVAL_LADDER[rungIndex].interval;\n    return {\n      interval,\n      next_date: GameProgressHandler.getDateIncrementedByInterval(dateAnswer, interval),\n    }\n  },\n\n  /**\n   * Compute whether the progress of the current learnable\n   * is now considered to be difficult\n   *\n   * @param dict progress\n   * @return bool\n   */\n  isDifficult: function(learnableProgress) {\n    if (learnableProgress.ignored || learnableProgress.not_difficult) {\n      return false;\n    }\n    if (learnableProgress.starred) {\n      return true;\n    }\n    if (learnableProgress.attempts === 1 || learnableProgress.total_streak >= 3) {\n      return false;\n    }\n    var ratio = learnableProgress.attempts > 0 ? learnableProgress.correct / learnableProgress.attempts : 1;\n\n    return learnableProgress.attempts < 6 && ratio < .75 || learnableProgress.attempts >= 6 && ratio < .92\n  },\n\n  /**\n   * Compute the attempts and streak for the given progress\n   *\n   * @param dict progress\n   * @param float score\n   * @return dict\n   */\n  setNextScreenStreak: function(learnableProgress, score) {\n    /*\n      \"when\": 1771925218,\n      \"interval\": 0.5,\n      \"total_streak\": -1,\n      \"current_streak\": 0,\n      \"correct\": 11,\n      \"attempts\": 12,\n      \"points\": 0,\n      \"score\": 0,\n    */\n    var isCorrect = score == 1;\n    return {\n      attempts       : learnableProgress.attempts + 1,\n      correct        : learnableProgress.correct + (isCorrect ? 1 : 0),\n      current_streak : isCorrect ? learnableProgress.current_streak + 1 : 0,\n      total_streak   : Math.max(learnableProgress.total_streak + (isCorrect ? 1 : -1), 0),\n    }\n  },\n\n  /**\n   * Create a new progress object from the saved on\n   * (send to memrise, will be used to trigger reviews)\n   */\n  copyProgress: function(learnableID, savedProgress) {\n    return {\n        learnable_id  : '' + learnableID,\n        starred       : savedProgress.starred || false,\n        ignored       : savedProgress.ignored || false,\n        not_difficult : savedProgress.not_difficult || false,\n\n        attempts      : savedProgress.attempts || 0,\n        correct       : savedProgress.correct || 0,\n        current_streak: savedProgress.current_streak || 0,\n        total_streak  : savedProgress.total_streak || 0,\n\n        created_date  : savedProgress.created_date || new Date(),\n        last_date     : new Date(),\n        next_date     : savedProgress.next_date || null,\n        interval      : savedProgress.interval || null,\n        growth_level  : savedProgress.growth_level || 0,\n    };\n  },\n\n  updateProgress: function(progress, score) {\n\n    // Update the progress\n    // progress.is_difficult = this.isDifficult(progress);\n    progress.growth_level = score == 1 ? GameProgressHandler.setNextScreenGrowthLevel(progress) : progress.growth_level;\n\n    // interval, next_date\n    Object.assign(progress, GameProgressHandler.setNextScreenIntervalDate(progress, progress.last_date, score));\n\n    // attempts, correct, current_streak, total_streak\n    Object.assign(progress, GameProgressHandler.setNextScreenStreak(progress, score));\n  },\n\n  // Send progress to memrise\n  registerEvent: function(courseID, learnableID, event) {\n    var learnable = GameDataBuilder.learnablesMap[learnableID] || {};\n\n    if (String(learnable.id) !== learnableID) {\n      console.error('Couldnt find learnable related to event', learnable, event);\n      return;\n    }\n\n    // Replace our custom game data to be compatible with memrise\n    if (event.box_template == 'reversed_multiple_choice2') {\n      event.box_template = 'reversed_multiple_choice';\n\n    } else if(event.box_template == 'reversed_typing') {\n      event.box_template = 'typing';\n      event.given_answer = (\n        event.score == 0 ? '' : GameScreenBuilder.flattenValue(learnable.screens['1'].definition.value)[0]\n      );\n    }\n\n    // Fluff up our event with required info\n    var item = event;\n\n    Object.assign(item, {\n      course_id          : parseInt(courseID),\n      learning_element   : learnable.learning_element,\n      definition_element : learnable.definition_element,\n    });\n\n    if(item.created_date) {\n      item.created_date = (item.created_date.getTime() / 1000) | 0;\n    }\n    if(item.next_date) {\n      item.next_date = (item.next_date.getTime() / 1000) | 0;\n    }\n    if(item.last_date) {\n      item.last_date = (item.last_date.getTime() / 1000) | 0;\n    }\n    item.when = item.last_date;\n\n    console.log('Event', learnable, item);\n    GameProgressHandler.events.push(item);\n  },\n\n  registerSessionEnd(data) {\n    var events = [...GameProgressHandler.events];\n    var requests = [];\n    console.log('Session end', data, events);\n\n    // Reset internal state\n    GameProgressHandler.events = [];\n    GameProgressHandler.isSaving = true;\n    $('#learn-settings-btn').addClass('loading-spinner-before');\n\n    // Send events in batches of 50\n    while(events.length) {\n      var batch = events.splice(0, 50);\n\n      requests.push({\n        url: '/ajax/register_progress',\n        method: 'POST',\n        data: JSON.stringify({\n          events: batch,\n        }),\n        contentType: 'application/json',\n      });\n    }\n\n    // Send session end\n    requests.push({\n      url: '/ajax/register_end',\n      method: 'POST',\n      data: JSON.stringify(data),\n      contentType: 'application/json',\n    });\n\n    // Send each request one after the other\n    this.executeRequestsList(requests);\n  },\n\n  executeRequestsList(requests) {\n    if(!requests.length) {\n      $('#learn-settings-btn').removeClass('loading-spinner-before');\n      GameProgressHandler.isSaving = false;\n      return;\n    }\n    var request = requests.pop();\n    $.ajax({\n      ...request,\n      complete: function(){\n        this.executeRequestsList([...requests]);\n      }.bind(this),\n    });\n  }\n};\n\n//+--------------------------------------------------------\n//| Render game\n//+--------------------------------------------------------\n\nclass Learn extends Component {\n  DISPLAY_CHOOSE_SCREEN = false;\n\n  // Values that are outside of the rendering logic\n  sessionSettings = {};\n\n  levelsIdList = [];\n  levelsLastId = 0;\n  useLevels = false; //!review entire course\n\n  // Screen utils\n  learnData = false;\n  template = null;\n  learnScreen_summary = false;\n\n  // Event utils\n  isScreenSubmitted = false;\n  isKeydownPressed = false;\n  isKeydownDelegated = false;\n\n  expectedChoiceKind = false;\n  choices = false;\n\n  //+--------------------------------------------------------\n  //| LIFECYCLE\n  //+--------------------------------------------------------\n\n  // Constructor\n  constructor(props) {\n    super(props);\n\n    if (window.$_GET && window.$_GET.display_debug_screen) {\n        this.DISPLAY_CHOOSE_SCREEN = true;\n    }\n\n    const state = {\n      isLoading: true,\n      levelId: 0,\n      levelType: 1,\n\n      error: false,\n      metaScreen: false,\n      learnScreen_i: 0,\n      learnScreen_n: 0,\n      learnScreen_enforcedTemplate: null,\n\n      points: 0,\n      hearts: 3,\n      userAnswer: null,\n    };\n\n    // review / learn / preview or any with a level_index\n    if(typeof this.props.level_index == 'number') {\n      this.levelsIdList = [parseInt(this.props.level_index)];\n      this.levelsLastId = this.levelsIdList[0] || 1;\n      this.useLevels = true;\n\n      state.levelId = this.levelsLastId;\n\n    // review without a level_index: review the course\n    } else if (this.props.session_type.endsWith('review')) {\n      this.levelsIdList = [];\n      this.levelsLastId = 0;\n      this.useLevels = false;\n\n      state.levelId = 'all';\n\n    // (all) learn / preview without a level_index: loop through the course's levels\n    } else{\n      this.levelsIdList = Array.prototype.sort.call(Object.keys(props.course.levels), (a, b) => parseInt(a) - parseInt(b));\n      this.levelsLastId = this.levelsIdList[this.levelsIdList.length-1] || 1;\n      this.useLevels = this.props.session_type == 'preview';  // request course | course_id_and_level_index\n\n      state.levelId = this.levelsIdList[0] || 1;\n    }\n    this.sessionSettings = {...window.MEMLIKE.sessionSettings};\n    this.state = state;\n\n    this.isScreenSubmitted = false;\n    this.isKeydownPressed = false;\n    this.isKeydownDelegated = false;\n\n    this.setChoices = this.setChoices.bind(this);\n    this.onSessionSettingsUpdated = this.onSessionSettingsUpdated.bind(this);\n  }\n\n  onSessionSettingsUpdated(settings) {\n    console.log('Session settings', settings);\n\n    Object.assign(this.sessionSettings, settings);\n  }\n\n  componentWillUnmount() {\n\n    // Remove all callbacks\n    window.modal.onOpen('learn', null);\n    window.modal.onClose('learn', null);\n  }\n\n  autoFocus() {\n    setTimeout(function(){\n      $('input[autofocus],.submit').first().focus();\n    }, 0);\n  }\n\n  resetScreenKeydown() {\n    this.isScreenSubmitted = false;\n    this.isKeydownPressed = false;\n    this.isKeydownDelegated = false;\n  }\n\n  onOpenModal() {\n    this.isKeydownPressed = false;\n    this.isKeydownDelegated = true; // Ignore all keyup events\n  }\n\n  onCloseModal() {\n    this.isKeydownDelegated = false;\n\n    // Re-triggered our autofocus\n    this.autoFocus();\n  }\n\n  // Initialization: retrieve datas via AJAX then bind events\n  componentDidMount() {\n    window.GlobalEventEmitter.subscribe('update-settings', this.onSessionSettingsUpdated);\n\n    window.modal.onClose('learn', this.onCloseModal.bind(this));\n    window.modal.onOpen('learn', this.onOpenModal.bind(this));\n\n    // When an image loads: remove the \"loading\" class & define its height\n    document.body.addEventListener('load', function(e){\n      if(e.target.tagName == 'IMG' && e.target.classList.contains('loading')){\n        e.target.classList.remove('loading');\n        e.target.parentNode.style.minHeight = e.target.height + 'px';\n      }\n    }, true); // <-- useCapture\n\n    // Retrieve data\n    this.fetchData(this.state.levelId, this.bindMainEvents.bind(this));\n  }\n\n  bindMainEvents() {\n    if(!this.props.preview_thing_id) {\n      window.onbeforeunload = this.warnbeforeunload.bind(this);\n    }\n\n    // Listen to keyboard inputs: next screen, multiple choice\n    $(window).on('keydown', this.keydown.bind(this));\n    $(window).on('keyup', this.keyup.bind(this));\n\n    // Submit\n    $('main').on('click', '.submit', function(e){\n      this.onSubmit(e);\n    }.bind(this));\n\n    // Typing\n    $('main').on('click', '.typing .button', function(e){\n      this.parentNode.previousElementSibling.value += this.innerHTML;\n      this.parentNode.previousElementSibling.focus();\n    });\n\n    // Tapping\n    $('main').on('click', '.tapping .button', function(){\n      var parent = this.parentNode;\n\n      if(parent.className == 'keyboard') {\n        parent.previousElementSibling.innerHTML += (\n          '<button class=\"button\" data-id=\"' + this.getAttribute('id') + '\">' + this.innerHTML + '</button>'\n        );\n        this.classList.add('disabled');\n\n      } else {\n        var id = this.getAttribute('data-id');\n        document.getElementById(id).classList.remove('disabled');\n        parent.removeChild(this);\n      }\n    });\n\n    // Multiple choice (handle the click the same way as using an access key)\n    $('main').on('click', '.choice-box', function(e){\n      this.selectTargetMultipleChoice(e.currentTarget.querySelector('input'));\n    }.bind(this));\n\n    // Hovering on audio: play audio\n    $('main').on('mouseover focus', '.choice-box.audio', function(e){\n      window.audioPlayer && window.audioPlayer.play.call(this.querySelector('audio'), e, true);\n\n    }).on('mouseleave', '.choice-box.audio', function(){\n      window.audioPlayer && window.audioPlayer.pause.call(this.querySelector('audio'));\n    });\n  }\n\n  // Every time screen gets updated\n  componentDidUpdate(prevProps, prevState) {\n    this.resetScreenKeydown();\n\n    // Triggered autofocus\n    this.autoFocus();\n\n    // Reset image zoom and audio player\n    window.imgZoom     && window.imgZoom.reset();\n    window.audioPlayer && window.audioPlayer.reset();\n\n    // Add text To Speech (TODO: clean that)\n    let ttsAdded = false;\n    if(window.TTS) {\n      $('.text[lang].tts').each(function(){\n        var url = window.TTS.getAudioURL(this.innerText, this.getAttribute('lang'));\n\n        if(url) {\n          var $audio = $('audio', this);\n          if($audio.length) {\n            $audio.attr('src', url);\n\n          } else {\n            var k = Date.now();\n            var elem = document.createElement('span');\n            elem.innerHTML = `\n              <audio id=\"audio-${k}\" src=${url}></audio>\n              <button type=\"button\" data-id=\"audio-${k}\" class=\"audio-player\" aria-label=\"${window.I18N.play_audio}\">\n                <i class=\"ico ico-l ico-audio\"></i>\n              </button>`;\n\n            this.appendChild(elem);\n            ttsAdded = true;\n          }\n        }\n      });\n    }\n\n    // Automatically play an audio track\n    // if there aren't any audio elements in the course, try the tts instead (outside .audio elements)\n    if (this.sessionSettings.enable_audio_autoplay) {\n      $('.autoplay .audio .audio-player').random().focus().trigger('click').length || (\n        ttsAdded && $('.autoplay .audio-player').random().focus().trigger('click')\n      );\n      this.autoFocus();\n    }\n\n    // Update level title (outside of react scope)\n    if(this.useLevels) {\n      if(!prevState.levelId || prevState.levelId != this.state.levelId) {\n        var name = '';\n        var idx = this.state.levelId;\n\n        if (idx < 1) {\n          idx += 1;\n        }\n        if (idx in this.props.course.levels) {\n          name = this.props.course.levels[idx].name;\n        }\n        var title = idx + (name ? ' - ' + name : '');\n        document.getElementById('level-title').innerHTML = title;\n      }\n    }\n\n    // Start the timer\n    if(this.state.metaScreen != 'correction') {\n      if(this.props.session_type == 'speed_review'){\n        Timer.start(this.submitSkip.bind(this));\n      }\n    }\n\n    // Debug screen\n    if (this.DISPLAY_CHOOSE_SCREEN) {\n      $('#debug-screen').on('click', 'li', function(e){\n        if(e.target.classList.contains('disabled')) return;\n\n        this.setState({\n          learnScreen_enforcedTemplate: e.target.innerHTML == 'default' ? false : e.target.innerHTML\n        });\n      }.bind(this));\n    }\n  }\n\n  /**\n   * Retrieve the current level data\n   */\n  fetchData(levelId, callback) {\n    var sessionType = this.props.session_type;\n    var levelType = 1;\n    var url = '/ajax' + this.props.course.url;\n\n    if(!this.useLevels) {\n      url += 'all/' + sessionType;\n    } else {\n      levelType = this.props.course.levels[levelId].type;\n\n      if(levelType === 2) {\n        url += levelId + '/media';\n      } else {\n        url += levelId + '/' + sessionType;\n      }\n    }\n\n    $.ajax({\n      url: url,\n      data: { session: this.props.session_id },\n      success: function(data){\n        callback && callback(data);\n\n        let error = false;\n        let metaScreen = false;\n        let learnScreen_n = 0;\n\n        this.learnScreen_summary = {\n          nb_scheduled_correct: 0,\n          nb_scheduled: 0,\n          learnables: {},\n        };\n\n        if (levelType === 2) {\n          metaScreen = 'markdown';\n\n          this.learnData = {\n            markdown: data,\n          };\n        } else {\n          let gameData = GameDataBuilder.buildData(sessionType, data);\n          if (!gameData.screens.length) {\n            switch (sessionType) {\n              case 'learn':\n                error = window.I18N.learn_err_empty_learn;\n                break;\n\n              case 'preview':\n                error = window.I18N.learn_err_empty_preview;\n                break;\n\n              case 'review':\n                error = window.I18N.learn_err_empty_review;\n                break;\n\n              default:\n                error = window.I18N.learn_err_empty;\n                break;\n            }\n          }\n          learnScreen_n = gameData.screens.length;\n          this.learnData = gameData;\n        }\n        this.setState({\n          isLoading: false,\n          levelId,\n          levelType,\n\n          error,\n          metaScreen,\n          learnScreen_i: 0,\n          learnScreen_n,\n        });\n      }.bind(this),\n\n      error: function(xhr) {\n        if(xhr.status == 403) {\n          this.setState({error: 403});\n        } else {\n          console.error(xhr.status + ' ' + xhr.statusText);\n          this.setState({error: 500});\n        }\n      }.bind(this),\n    });\n  }\n\n  //+--------------------------------------------------------\n  //| EVENTS\n  //+--------------------------------------------------------\n\n  // Trigger warning when user closes tab\n  warnbeforeunload(e) {\n    this.isScreenSubmitted = false;\n    console.log('warnbeforeunload', e);\n\n    if(GameProgressHandler.isSaving) {\n      // pass\n    } else if(this.state.metaScreen == 'summary' || this.state.metaScreen == 'lost' || this.state.error) {\n      return;\n    }\n    var msg = 'Your changes will be lost.';\n\n    e = e || window.event;\n    if (e) { // IE, Firefox < 4\n      e.returnValue = msg;\n    }\n    return msg;\n  }\n\n  keydown(e) {\n    if (this.isKeydownDelegated) {\n      return;\n    }\n    this.isKeydownPressed = true;\n  }\n\n  // Listen to keyboard inputs: next screen, multiple choice answer\n  keyup(e) {\n\n    // Losing focus after rendering / delegating keydown in a modal\n    if (!this.isKeydownPressed) {\n      return;\n    }\n    var key = e.which;\n\n    // Press enter\n    if(key == 13) {\n\n      // No focused element\n      if (e.target === document.body) {\n        return;\n      }\n\n      // Cut short redundancy between button click and enter\n      if (this.isScreenSubmitted) {\n        return;\n      }\n\n      // On the presentation screen: pressing enter on a button = trigger the button\n      if (0&&!this.expectedChoiceKind) {\n        if(e.target.classList.contains('button')) {\n          if(!e.target.classList.contains('disabled')) {\n            e.target.click();\n          }\n          return;\n        }\n      }\n      if(e.target.type === 'radio' && e.target.checked === false) {\n        e.target.checked = true;\n        return;\n      }\n\n      // Submit the form\n      return this.onSubmit(e);\n    }\n\n    // Select a component through its acceskey\n    if(this.expectedChoiceKind == 'accesskey' && key > 96 && key <= 105) {\n      var accesskey = fromKeyCode(key);\n\n      var input = document.getElementById(`choice-${accesskey}`); // .choice-box[accesskey=\"${char}\"]\n      if (!input) {\n        return;\n      }\n      this.selectTargetMultipleChoice(input);\n    }\n  }\n\n  onSubmit(e) {\n    e.preventDefault();\n    e.stopPropagation();\n\n    // Wait for a new render before listening to submits\n    if (this.isScreenSubmitted) {\n      return;\n    }\n    this.isScreenSubmitted = true;\n\n    Timer.stop();\n\n    // Presentation\n    if(!this.expectedChoiceKind) {\n      this.setNextScreen();\n\n    // Typing\n    } else if(this.expectedChoiceKind == 'text') {\n      this.submitText($('.typing input').val() || '');\n\n    // Tapping\n    } else if(this.expectedChoiceKind == 'tapping') {\n      var chosen = [];\n      $('.tapping .input button').each(function(){\n        chosen.push(this.innerHTML);\n      });\n      this.submitTapping(chosen);\n\n    // Numeric\n    } else if(this.expectedChoiceKind == 'accesskey') {\n      this.submitMultipleChoice($('.choice-box input:checked').attr('accesskey') || '');\n\n    } else {\n      console.info('Skipping', this.expectedChoiceKind);\n      this.submitSkip();\n    }\n  }\n\n  //+--------------------------------------------------------\n  //| GAME COMPUTATIONS\n  //+--------------------------------------------------------\n\n  submitSkip() {\n    this.accountUserAnswer({\n      value : '',\n      score : 0,\n      kind  : ''\n    });\n  }\n\n  // Text entry: User submit its answer\n  submitText(givenAnswer) {\n    givenAnswer = givenAnswer.trim();\n\n    // Text input\n    var sanitizedGivenAnswer = sanitizeTyping(givenAnswer, this.is_strict);\n    var score   = 0,\n        rightAnswer = '',\n        s;\n\n    // If not is_strict, memrise adds lowercase version to .correct answers\n    var check_case = !this.is_strict && window.MEMLIKE.sessionSettings.strict_case;\n    var stack = {};\n\n    if (givenAnswer) {\n      for(let i=0; i<this.choices.length; i++) {\n        var choice = this.choices[i];\n\n        if (check_case && stack[choice.toLowerCase()]) {\n          continue;\n        }\n        stack[choice.toLowerCase()] = 1;\n\n        choice = sanitizeTyping(choice, this.is_strict),\n        s      = ScoreAnswer.computeScore(sanitizedGivenAnswer, choice);\n\n        if(s && s > score) {\n          score = s;\n          rightAnswer = choice;\n        }\n      }\n    }\n\n    this.accountUserAnswer({\n      value    : givenAnswer,\n      testValue: sanitizedGivenAnswer,\n      refValue : rightAnswer,\n      score    : score,\n      kind     : 'text'\n    });\n  }\n\n  // Tapping: User order words\n  submitTapping(entry) {\n    var isValid = 0;\n    entry = entry.join(' ').trim();\n\n    for(var i=0; i<this.choices.length; i++) {\n      if(entry == this.choices[i].join(' ').trim()) {\n        isValid = 1;\n        break;\n      }\n    }\n\n    this.accountUserAnswer({\n      value : entry,\n      score : isValid ? 1 : 0,\n      kind  : 'text'\n    });\n  }\n\n  // Multiple choice: User chooses a answer\n  submitMultipleChoice(accesskey) {\n    if (!accesskey) {\n      return this.submitSkip();\n    }\n\n    // Retrieve the choice associated to the current number\n    var idx = parseInt(accesskey)-1;\n    if (isNaN(idx) || idx >= this.choices.length) {\n      return this.submitSkip();\n    }\n    var choice = idx < this.choices.length ? this.choices[idx].attributes : '';\n\n    // Check if we got the right answer\n    this.accountUserAnswer({\n      value : choice.value,\n      score : choice.isValid ? 1 : 0,\n      kind  : choice.answerType,\n      i     : idx\n    });\n  }\n\n  updateSummary(learnableID, isCorrect) {\n\n    // Count right and wrong answers\n    this.learnScreen_summary.nb_scheduled += 1;\n    this.learnScreen_summary.nb_scheduled_correct += (isCorrect ? 1 : 0);\n\n    var learnablesSummary = this.learnScreen_summary.learnables;\n    if(!learnablesSummary[learnableID]) {\n      learnablesSummary[learnableID] = {\n        count: 0,\n        right: 0,\n        index: Object.keys(learnablesSummary).length,\n      };\n    }\n    learnablesSummary[learnableID].count++;\n    if(isCorrect) {\n      learnablesSummary[learnableID].right++;\n    }\n  }\n\n  updatePoints(learnableID, userAnswer, timeSpent) {\n    var template = this.template;\n\n    // Update the streak status and next review data\n    // Values from this object are incremented each time this learnable is learned\n    // and retrieved from the backend at the beginning of the learning session\n    var progress = GameProgressHandler.copyProgress(\n      learnableID,\n      this.learnData.progressMap[learnableID] || {},\n    );\n    GameProgressHandler.updateProgress(\n      progress,\n      userAnswer.score,\n    );\n    this.learnData.progressMap[learnableID] = progress;\n\n    // Update the earned points\n    var points = AwardPoints.getPoints(\n      this.props.session_type,\n      template,\n      timeSpent,\n      userAnswer.score,\n      progress.current_streak,\n    );\n\n    // Values from this object are send to the backend for stats\n    // But don't have an impact for the next learning session\n    this.sessionSettings.save_progress && setTimeout(() => {\n      var event = {\n          learnable_id : learnableID,\n          box_template : template,\n          given_answer : userAnswer.value,\n          score        : userAnswer.score,\n          time_spent   : timeSpent,\n          points       : points,\n          bonus_points : 0,\n      };\n      Object.assign(event, progress);\n\n      GameProgressHandler.registerEvent(this.props.course.id, learnableID, event);\n    }, 0);\n\n    return points;\n  }\n\n  // Answer has been submitted and checked: compute progress, points & give feedback\n  // userAnswer: {value,score,kind,...rest}\n  accountUserAnswer(userAnswer) {\n    var isSpeedReview = this.props.session_type == 'speed_review';\n\n    // Show the correct answer\n    if(isSpeedReview) {\n      this.selectCorrectMultipleChoice(userAnswer);\n    }\n    var screen = this.learnData ? this.learnData.screens[this.state.learnScreen_i] : null;\n    if(!screen) {\n      return;\n    }\n    var learnableID = screen.learnableID,\n        isCorrect   = userAnswer.score == 1,\n        time_spent  = 0,\n        hearts      = this.state.hearts;\n\n    // Update the hearts\n    if (isSpeedReview) {\n      time_spent = Timer.getTime();\n\n      if (!isCorrect) {\n        hearts -= 1;\n        $('.hearts-wrapper .heart.full').last().addClass('empty').removeClass('full');\n      }\n    }\n\n    // Count right and wrong answers\n    this.updateSummary(learnableID, isCorrect);\n\n    // Count points & save progress\n    var points = this.updatePoints(learnableID, userAnswer, time_spent);\n\n    // Display correction\n    if(!isSpeedReview) {\n      return this.setState({\n        metaScreen: 'correction',\n        userAnswer,\n        learnScreen_enforcedTemplate: false,\n        points: this.state.points + points,\n      });\n    }\n\n    // Update hearts / overlay / classes\n    var newState = {\n      hearts,\n      points: this.state.points + points,\n    }\n    if(hearts == 0) {\n      newState.metaScreen = 'lost';\n\n      // Show the overlay without updating the screen underneath\n      Object.assign(this.state, newState);\n\n      this.resetScreenKeydown();\n\n      $(document.body).append(`<div class=\"overlay\">\n        <div class=\"no-heart\"></div>\n        <p class=\"overlay-text\">${window.I18N.no_more_hearts} !</p>\n        <div class=\"btn-group\">\n          <a href=\"${window.MEMLIKE.garden.session_origin_url}\">${window.I18N.return}</a>\n          <a href=\"${window.location.href}\">${window.I18N.replay}</a>\n        </div>\n      </div>`);\n\n    } else {\n      setTimeout(function(){\n        $('.choice-box').removeClass('correct').removeClass('incorrect');\n\n        this.setNextScreen(newState);\n      }.bind(this), isCorrect ? 500 : 3000);\n    }\n  }\n\n  selectTargetMultipleChoice(radioElement) {\n    radioElement.focus();\n\n    if (radioElement.checked) {\n      radioElement.checked = false;\n      return;\n    }\n    radioElement.checked = true;\n\n    //$(target).addClass('active').siblings('.choice-box').removeClass('active');\n\n    let audioElement = radioElement.parentNode.querySelector('audio');\n    if (audioElement) {\n      window.audioPlayer && window.audioPlayer.play.call(audioElement, null, true);\n    }\n  }\n\n  selectCorrectMultipleChoice(userAnswer) {\n\n    // Update the class of the selected choice (accesskey-1)\n    if('i' in userAnswer) {\n      $('#choice-' + (userAnswer.i+1)).parent().addClass(userAnswer.score == 1 ? 'correct' : 'incorrect');\n    }\n\n    // Update the class of the correct choice\n    if(userAnswer.score != 1) {\n      for(var j=0; j<this.choices.length; j++) {\n        if(this.choices[j].attributes.isValid) {\n          $('#choice-' + (j+1)).parent().addClass('correct');\n          break;\n        }\n      }\n    }\n  }\n\n  // Display next screen\n  setNextScreen(newState) {\n    this.expectedChoiceKind = false;\n\n    newState = newState || {}\n\n    // We're not expecting a submit there\n    if (this.state.error || this.state.isLoading) {\n      return;\n    }\n\n    if (this.state.levelType == 1) {\n\n      // Next screen\n      if(this.state.learnScreen_i + 1 < this.state.learnScreen_n) {\n        return this.setState(Object.assign(newState, {\n          learnScreen_i: this.state.learnScreen_i + 1,\n          metaScreen: false,\n          userAnswer: null,\n        }));\n      }\n\n      // Reached the last screen: recap the list of learned things (= summary)\n      if (!this.state.metaScreen || this.state.metaScreen == 'correction') {\n\n        // Save session points\n        var data = {\n          session_points: this.state.points,\n          session_type: this.props.session_type == 'classic_review' ? 'review' : this.props.session_type,\n          session_source_type: this.useLevels ? 'course_id_and_level_index' : 'course',\n          session_source_id: this.props.course.id,\n        };\n        if (this.useLevels) {\n          data.session_source_sub_index = this.state.levelId;\n        }\n        this.sessionSettings.save_progress && setTimeout(() => {\n          GameProgressHandler.registerSessionEnd(data);\n        }, 0);\n\n        // Display the summary\n        return this.setState(Object.assign(newState, {\n          learnScreen_i: this.state.learnScreen_n,\n          metaScreen: 'summary',\n          userAnswer: null,\n        }));\n      }\n    }\n\n    // If we're looping through the levels: display the next level\n    if(this.useLevels && this.state.levelId < this.levelsLastId) {\n      let levelId = this.levelsIdList[this.levelsIdList.indexOf(this.state.levelId) + 1];\n\n      // Reinit our internal variables (even though fetchData is supposed to build them)\n      this.resetScreenKeydown();\n      this.resetChoices();\n\n      this.learnData = false;\n      this.learnScreen_summary = false;\n      this.template = null;\n\n      // Reinit our state: display the loader\n      this.setState({\n        isLoading: true,\n        levelId,\n        levelType: 1,\n\n        error: false,\n        metaScreen: false,\n        learnScreen_i: 0,\n        learnScreen_n: 0,\n        learnScreen_enforcedTemplate: null,\n\n        points: 0,\n        hearts: 3,\n        userAnswer: null,\n      });\n\n      // Fetch the level data\n      return this.fetchData(levelId);\n    }\n\n    // We reached the last level to display: go back to the course\n    window.location.href = window.MEMLIKE.garden.session_origin_url;\n  }\n\n  //+--------------------------------------------------------\n  //| RENDERING\n  //+--------------------------------------------------------\n\n  resetChoices() {\n    this.expectedChoiceKind = false;\n    this.choices = false;\n  }\n\n  setChoices(choices, type, is_strict) {\n    this.expectedChoiceKind = type; // accesskey | text | tapping\n    this.choices = choices; // list of components if expectedChoiceKind == accesskey\n\n // values in parentheses and punctuation should match too?\n    this.is_strict = typeof is_strict == 'undefined' ? 1 : is_strict;\n  }\n\n  render() {\n    this.isKeydownPressed = false;\n\n    // Loading data\n    if(this.state.isLoading) {\n      return <div className=\"loading-spinner\"></div>;\n    }\n\n\n    // Something went wrong\n    if(this.state.error) {\n      if(this.state.error == 403) {\n        return <p>{window.I18N._403} <a href=\"/login\" className=\"link\">{window.I18N.login}</a></p>;\n      } else if (typeof this.state.error == 'string') {\n        return <p>{this.state.error}</p>;\n      } else {\n        return <p>{window.I18N.error}</p>;\n      }\n    }\n\n    // Media level (state.levelType == 2)\n    if (this.state.metaScreen == 'markdown') {\n      return this.renderMarkdownScreen();\n    }\n\n    // Preview thing\n    if(this.props.preview_thing_id) {\n\n      // Utils for devs: render the specific screen for the given thing\n      if(this.state.learnScreen_enforcedTemplate) {\n        return this.renderLearnScreen();\n      } else {\n        return <div>\n          {this.DISPLAY_CHOOSE_SCREEN ? this.renderChooseLearnScreen() : null}\n          {this.renderLearnScreen_presentation(false)}\n        </div>;\n      }\n    }\n\n    // ie Summary, correction, lost\n    // Cut short and display learnScreen without chrono / debug screen\n    if(this.state.metaScreen) {\n      return (\n        <div>\n          {this.renderLearnProgressBar()}\n          {this.renderLearnScreen()}\n          <button type=\"button\" className=\"btn submit\" tabIndex=\"0\">{window.I18N.next}</button>\n        </div>\n      );\n    }\n\n    return (\n      <div>\n        {this.DISPLAY_CHOOSE_SCREEN && this.renderChooseLearnScreen()}\n\n        {/* POINTS, HEARTS, PROGRESS BAR */}\n        {this.renderLearnProgressBar()}\n\n        {/* SCREEN */}\n        {this.props.session_type == 'speed_review'\n          ? <div className=\"speed_review\"><div id=\"speed_review-timer\" key={Date.now()}></div>{this.renderLearnScreen()}</div>\n          : this.renderLearnScreen()}\n\n        <button type=\"button\" className=\"btn submit\" tabIndex=\"0\">{window.I18N.next}</button>\n      </div>\n    );\n  }\n\n  renderLearnProgressBar() {\n    var percent = (this.state.learnScreen_n ? Math.ceil(this.state.learnScreen_i / this.state.learnScreen_n * 100) : 100);\n\n    return <div className=\"progress-stats\">\n      {this.props.session_type == 'speed_review' &&\n        <div className=\"hearts-wrapper\">{[1,2,3].map((i) => (\n          <span key={i} className={'heart ' + (i <= this.state.hearts ? 'full' : 'empty')}></span>\n          ))}\n        </div>}\n      <div className=\"points-num\">{this.state.points}</div>\n\n      <div\n        className=\"progress-bar\"\n        role=\"progressbar\"\n        aria-valuenow={this.state.learnScreen_i}\n        aria-valuemin=\"0\"\n        aria-valuemax={this.state.learnScreen_i}\n      >\n        <div className=\"counter\">{this.state.learnScreen_i} / {this.state.learnScreen_n}</div>\n        <div className=\"progress-bar-active\" style={{'clip-path': 'polygon(0 0, '+percent+'% 0, '+percent+'% 100%, 0 100%)'}}>\n          <div className=\"counter\">{this.state.learnScreen_i} / {this.state.learnScreen_n}</div>\n        </div>\n      </div>\n    </div>;\n  }\n\n  renderChooseLearnScreen() {\n    var item    = this.learnData.screens[this.state.learnScreen_i],\n        screen  = this.learnData.screensTemplateMap[item.learnableID],\n        current = this.state.learnScreen_enforcedTemplate;\n\n    return <ul id=\"debug-screen\">\n      <li className={current ? '' : 'active'}>default</li>\n      <li className={('multiple_choice' in screen && screen.multiple_choice ? '' : 'disabled')\n              + (current == 'multiple_choice' ? ' active' : '')}>\n        multiple_choice\n      </li>\n      <li className={('typing' in screen && screen.typing ? '' : 'disabled')\n              + (current == 'typing' ? ' active' : '')}>\n        typing\n      </li>\n      <li className={('reversed_multiple_choice' in screen && screen.reversed_multiple_choice ? '' : 'disabled')\n              + (current == 'reversed_multiple_choice' ? ' active' : '')}>\n        reversed_multiple_choice\n      </li>\n      <li className={('audio_multiple_choice' in screen && screen.audio_multiple_choice ? '' : 'disabled')\n              + (current == 'audio_multiple_choice' ? ' active' : '')}>\n        audio_multiple_choice\n      </li>\n      <li className={('tapping' in screen && screen.tapping ? '' : 'disabled')\n              + (current == 'tapping' ? ' active' : '')}>\n        tapping\n      </li>\n      <li className={('typing' in screen && screen.typing ? '' : 'disabled')\n              + (current == 'copytyping' ? ' active' : '')}>\n        copytyping\n      </li>\n      <li className={('typing' in screen && screen.typing.audio ? '' : 'disabled')\n              + (current == 'audio_typing' ? ' active' : '')}>\n        audio_typing\n      </li>\n      <li className={('reversed_multiple_choice' in screen && screen.reversed_multiple_choice.prompt.video ? '' : 'disabled')\n              + (current == 'reversed_multiple_choice_prompt_video' ? ' active' : '')}>\n        reversed_multiple_choice_prompt_video\n      </li>\n      <li className={('multiple_choice' in screen && screen.multiple_choice.prompt.video ? '' : 'disabled')\n              + (current == 'video-pre-presentation' ? ' active' : '')}>\n        video-pre-presentation\n      </li>\n      <li className={(screen.presentation ? '' : 'disabled')\n              + (current == 'presentation' ? ' active' : '')}>\n        presentation\n      </li>\n    </ul>;\n  }\n\n  renderLearnScreen() {\n    this.resetChoices();\n\n    if(!this.learnData) {\n      return null;\n    }\n    if(this.state.learnScreen_enforcedTemplate) {\n      switch(this.state.learnScreen_enforcedTemplate) {\n        case 'multiple_choice'         : return this.renderLearnScreen_any({ template: 'multiple_choice' });\n        case 'typing'                  : return this.renderLearnScreen_any({ template: 'typing' });\n        case 'reversed_multiple_choice': return this.renderLearnScreen_any({ template: 'reversed_multiple_choice' });\n        case 'audio_multiple_choice'   : return this.renderLearnScreen_any({ template: 'audio_multiple_choice' });\n        case 'tapping'                 : return this.renderLearnScreen_any({ template: 'tapping' });\n        case 'copytyping'              : return this.renderLearnScreen_any({ template: 'copytyping' });\n        case 'audio_typing'            : return this.renderLearnScreen_any({ template: 'typing', promptWith: 'audio' });\n        case 'reversed_multiple_choice_prompt_video': return this.renderLearnScreen_any({ template: 'reversed_multiple_choice', promptWith: 'video' });\n        case 'video-pre-presentation'  : return this.renderLearnScreen_any({ template: 'multiple_choice', promptWith: 'video' });\n        case 'presentation'            : return this.renderLearnScreen_any({ template: 'presentation' });\n      }\n    }\n    if(this.state.metaScreen == 'summary') {\n      return this.renderLearnScreen_summary();\n    }\n    if(this.state.metaScreen == 'correction') {\n      return this.renderLearnScreen_presentation(this.state.userAnswer || true);\n    }\n\n    // No defined screen: display next learnable\n    const item = this.learnData.screens[this.state.learnScreen_i];\n    if(!item) {\n      console.log('No item to display', this.learnData.screens, this.state.learnScreen_i);\n      return null;\n    }\n    const screens = this.learnData.screensTemplateMap[item.learnableID];\n    if(!screens) {\n      console.log('No screen to display', this.learnData.screensTemplateMap, item);\n      return null;\n    }\n    console.log('Screen', item, screens);\n\n    if(item.learningGrowthLevel) {\n      switch(item.learningGrowthLevel) {\n        case 1:\n            return this.renderLearnScreen_any({\n              template: 'multiple_choice',\n              nChoices: 4,\n            });\n\n        case 2:\n          if(screens.reversed_multiple_choice.video && !this.sessionSettings.disable_multimedia) {\n            return this.renderLearnScreen_any({\n              template: 'reversed_multiple_choice',\n              nChoices: 4,\n              promptWith: 'video',\n            });\n          }\n          if(screens.audio_multiple_choice && Math.random() > .5 && !this.sessionSettings.disable_multimedia) {\n            return this.renderLearnScreen_any({\n              template: 'audio_multiple_choice',\n            });\n          }\n          if(screens.tapping && !this.sessionSettings.disable_tapping) {\n            return this.renderLearnScreen_any({\n              template: 'tapping',\n              difficulty: 0,\n            });\n          }\n          return this.renderLearnScreen_any({\n            template: 'reversed_multiple_choice',\n            nChoices: 4,\n          });\n\n        case 3:\n          if(screens.tapping && !this.sessionSettings.disable_tapping) {\n            return this.renderLearnScreen_any({\n              template: 'tapping',\n              difficulty: .5,\n            });\n          }\n          if(screens.typing && !this.sessionSettings.disable_typing) {\n            return this.renderLearnScreen_any({\n              template: 'typing',\n            });\n          }\n          return this.renderLearnScreen_any({\n            template: 'multiple_choice',\n            nChoices: 9,\n          });\n\n        case 4:\n          if(screens.multiple_choice.video && !this.sessionSettings.disable_multimedia) {\n            return this.renderLearnScreen_any({\n              template: 'reversed_multiple_choice',\n              nChoices: 4,\n              promptWith: 'video',\n            });\n          }\n          if(Math.random() > .5 && !this.sessionSettings.disable_multimedia) {\n            var s = [];\n            if(screens.typing.audio && !this.sessionSettings.disable_typing) {\n              s.push({\n                template: 'typing',\n                promptWith: 'audio',\n              });\n            }\n            if(screens.reversed_multiple_choice.audio && !this.sessionSettings.disable_multimedia) {\n              s.push({\n                template: 'reversed_multiple_choice',\n                nChoices: 4,\n                promptWith: 'audio',\n              });\n            }\n            if(s.length > 0) {\n              return this.renderLearnScreen_any(s.random());\n            }\n          }\n          return this.renderLearnScreen_any({\n            template: 'reversed_multiple_choice',\n            nChoices: [4, 6].random(),\n          });\n\n        case 5:\n          if(screens.taping && !this.sessionSettings.disable_tapping) {\n            return this.renderLearnScreen_any({\n              template: 'tapping',\n              difficulty: .5,\n            });\n          }\n          return this.renderLearnScreen_any({\n            template: 'multiple_choice',\n            nChoices: [6, 9].random(),\n          });\n\n        default:\n          if(screens.typing && !this.sessionSettings.disable_typing) {\n            return this.renderLearnScreen_any({\n              template: 'typing',\n            });\n          }\n          return {\n            template: 'multiple_choice',\n            nChoices: 9,\n          };\n      }\n    }\n\n    if(this.props.session_type == 'speed_review') {\n      if(this.sessionSettings.reverse_prompt_and_answer && screens.reversed_multiple_choice) {\n        return this.renderLearnScreen_any({\n          template: 'reversed_multiple_choice',\n          nChoices: 4,\n        });\n      }\n      return this.renderLearnScreen_any({\n        template: 'multiple_choice',\n        nChoices: 4,\n      });\n    }\n\n    if (item.template == 'sentinel') {\n\n      // Reversing Question on the answer, answer with the question\n      if(this.sessionSettings.reverse_prompt_and_answer) {\n        if(screens.typing\n          && !this.sessionSettings.disable_typing\n          && GameScreenBuilder.buildScreen_reverse_typing(screens, this.props.course.source)\n        ) {\n          return this.renderLearnScreen_any({\n            template: 'reversed_typing',\n          });\n        }\n        return this.renderLearnScreen_any({\n            template: (GameScreenBuilder.buildScreen_reversed_multiple_choice(screens), 'reversed_multiple_choice2'),\n            nChoices: 9,\n        });\n      }\n\n      if(screens.typing && !this.sessionSettings.disable_typing) {\n        return this.renderLearnScreen_any({\n          template: 'typing',\n        });\n      }\n      if(screens.audio_multiple_choice && Math.random() > .5 && !this.sessionSettings.disable_multimedia) {\n        return this.renderLearnScreen_any({\n          template: 'audio_multiple_choice',\n        });\n      }\n      return this.renderLearnScreen_any({\n          template: 'multiple_choice',\n          nChoices: 9,\n      });\n    }\n\n    return this.renderLearnScreen_any({ template: item.template });\n  }\n\n  renderLearnScreen_any(setting) {\n    this.template = setting.template;\n\n    switch(setting.template) {\n      case 'multiple_choice': return this.renderLearnScreen_multiple_choice(setting);\n      case 'reversed_typing': return this.renderLearnScreen_reversed_typing(setting);\n      case 'typing': return this.renderLearnScreen_typing(setting);\n      case 'reversed_multiple_choice': return this.renderLearnScreen_reversed_multiple_choice(setting);\n      case 'reversed_multiple_choice2': return this.renderLearnScreen_reversed_multiple_choice2(setting);\n      case 'audio_multiple_choice': return this.renderLearnScreen_audio_multiple_choice(setting);\n      case 'tapping': return this.renderLearnScreen_tapping(setting);\n      case 'copytyping': return this.renderLearnScreen_copytyping(setting);\n      case 'presentation':\n        return this.renderLearnScreen_presentation();\n      default:\n        console.error(setting.template + \" doesn't exist\");\n    }\n  }\n  getLearnScreen(tpl) {\n    /*\n    Returns the current screen data\n    Exemple:\n        {\n          \"template\": \"multiple_choice\",\n          \"prompt\": {\n            \"text\": {\n              \"label\": \"French\",\n              \"kind\": \"text\",\n              \"value\": \"Vois-tu le chien ?\",\n              \"alternatives\": [],\n              \"style\": [],\n              \"direction\": \"source\",\n              \"markdown\": false\n            },\n            \"audio\": null,\n            \"video\": null,\n            \"image\": null\n          },\n          \"answer\": {\n            \"label\": \"German\",\n            \"kind\": \"text\",\n            \"value\": \"Siehst du den Hund ?\",\n            \"alternatives\": [],\n            \"style\": [],\n            \"direction\": \"target\",\n            \"markdown\": false\n          },\n          \"correct\": [\n            \"Siehst du den Hund ?\"\n          ],\n          \"choices\": [\n            \"Siehst du das Pferd ?\",\n            \"Siehst du die Katze ?\",\n            \"Siehst du die Tiere ?\",\n            \"Die Tiere sind süß\",\n            \"Der Hund ist süß\",\n            \"Gib der Katze des Essen\",\n            \"Gib dem Hund das Essen\",\n            \"Die Katze ist süß\",\n            \"Es ist das Essen des Hundes\",\n            \"Es ist das Essen des Pferdes\",\n            \"Es ist das Essen der Tiere\",\n            \"Das Pferd ist süß\"\n          ],\n          \"audio\": null,\n          \"markdown\": false,\n          \"attributes\": [\n            {\n              \"label\": \"Gender\",\n              \"value\": \"der Hund\"\n            }\n          ],\n          \"post_answer_info\": null,\n          \"placeholder\": null,\n          \"feedback_screen\": null,\n          \"is_strict\": false,\n          \"translation_prompt\": null,\n          \"gap_prompt\": null\n        }\n    */\n    var learnableID = this.props.preview_thing_id || this.learnData.screens[this.state.learnScreen_i].learnableID;\n\n    return this.learnData.screensTemplateMap[learnableID][tpl];\n  }\n\n  renderLearnScreen_audio_multiple_choice(setting) {\n    return <MultipleChoice\n              item={this.getLearnScreen('audio_multiple_choice')}\n              nChoices={setting.nChoices || 4}\n              promptWith={setting.promptWith}\n              setChoices={this.setChoices} />;\n  }\n  renderLearnScreen_reversed_multiple_choice(setting) {\n    return <MultipleChoice\n              item={this.getLearnScreen('reversed_multiple_choice')}\n              nChoices={setting.nChoices || 4}\n              promptWith={setting.promptWith}\n              setChoices={this.setChoices} />;\n  }\n  renderLearnScreen_reversed_multiple_choice2(setting) {\n    return <MultipleChoice\n              item={this.getLearnScreen('reversed_multiple_choice2')}\n              nChoices={setting.nChoices || (this.props.session_type == 'speed_review' ? 4 : 9)}\n              setChoices={this.setChoices} />;\n  }\n  renderLearnScreen_multiple_choice(setting) {\n    return <MultipleChoice\n              item={this.getLearnScreen('multiple_choice')}\n              nChoices={setting.nChoices || (this.props.session_type == 'speed_review' ? 4 : 9)}\n              promptWith={setting.promptWith}\n              setChoices={this.setChoices} />;\n  }\n  renderLearnScreen_reversed_typing(setting) {\n    return <Typing\n              item={this.getLearnScreen('reversed_typing')}\n              setChoices={this.setChoices} />;\n  }\n  renderLearnScreen_typing(setting) {\n    return <Typing\n              item={this.getLearnScreen('typing')}\n              setChoices={this.setChoices}\n              promptWith={setting.promptWith} />;\n  }\n  renderLearnScreen_tapping(setting) {\n    return <Tapping\n              item={this.getLearnScreen('tapping')}\n              difficulty={setting.difficulty || 1}\n              setChoices={this.setChoices} />;\n  }\n  renderLearnScreen_copytyping(){\n    var prompt = this.getLearnScreen('typing');\n    this.setChoices(prompt.correct, 'text', prompt.is_strict);\n\n    return <Presentation\n              item={this.getLearnScreen('presentation')}\n              prompt={prompt}\n            />;\n  }\n  renderLearnScreen_presentation(userAnswer) {\n    return (\n      <Presentation\n        item={this.getLearnScreen('presentation')}\n        userAnswer={userAnswer}\n        langCodeTarget={this.props.course.target ? this.props.course.target.language_code : null}\n        langCodeSource={this.props.course.source ? this.props.course.source.language_code : null}\n        disableMultimedia={false}\n      />\n    );\n  }\n  renderLearnScreen_summary() {\n    var items = [];\n\n    if(this.props.session_type == 'preview') {\n      if(this.learnData) {\n        for(var i=0; i<this.learnData.screens.length; i++) {\n          var id = '' + this.learnData.screens[i].learnableID;\n\n          items.push(this.learnData.screensTemplateMap[id].presentation);\n        }\n      }\n    } else {\n      for(var id in this.learnScreen_summary.learnables) {\n        var item = this.learnScreen_summary.learnables[id];\n\n        items[item.index] = {...item, ...this.learnData.screensTemplateMap[id].presentation};\n      }\n    }\n    return <Summary items={Object.values(items)} session_type={this.props.session_type} />;\n  }\n  renderMarkdownScreen() {\n    var txt = this.learnData.markdown;\n    var data = txt ? window.markdown.decode(eval(txt)) : '';\n    return <div className=\"nicebox\" dangerouslySetInnerHTML={{__html: data}} />;\n  }\n}\n\nconst Value = function(props) {\n  var content   = props.content,\n      attrs     = {},\n      className = props.className || '';\n  if(props.lang) {\n    attrs.lang = props.lang;\n  }\n  var k = Date.now(),\n      i = 0;\n\n  if(props.single) {\n    switch(props.type) {\n      case 'text' : return (\n        <span>{content}</span>\n      );\n      case 'image': return (\n        <img key={k} src={content} className=\"text-image\" />\n      );\n      case 'audio': return (\n        <span key={k}>\n          <audio id={'audio-' + k} src={content}></audio>\n          <button type=\"button\" data-id={'audio-' + k} className=\"audio-player\" aria-label={window.I18N.play_audio}>\n            <i className=\"ico ico-l ico-audio\"></i>\n          </button>\n        </span>\n      );\n      case 'video': return (\n        <video key={k} src={content} className=\"video-player\" controls autoPlay>\n          Your browser does not support the video tag.\n        </video>\n      );\n    }\n  } else {\n    switch(props.type) {\n      case 'text' : return (\n        <div className={'text ' + className} {...attrs}>{content}</div>\n      );\n      case 'image': return (\n        <div className=\"image\">\n          <div className=\"media-list\">{content.map(media => (\n            <img key={k + i++} src={media} className=\"text-image loading\" />\n          ))}</div>\n        </div>\n      );\n      case 'audio': return (\n        <div className=\"audio\">\n          <div className=\"media-list\">{content.map(media => (\n            <span key={k + i++}>\n              <audio id={'audio-' + (k + i)} src={media.normal}></audio>\n              <button type=\"button\" data-id={'audio-' + (k + i)} className=\"audio-player\" aria-label={window.I18N.play_audio}>\n                <i className=\"ico ico-l ico-audio\"></i>\n              </button>\n            </span>\n          ))}</div>\n        </div>\n      );\n      case 'video': return (\n        <div className=\"video\">\n          <div className=\"media-list\">\n            <video key={k + i++} src={content.random()} className=\"video-player\" controls autoPlay>\n              Your browser does not support the video tag.\n            </video>\n          </div>\n        </div>\n      );\n    }\n  }\n};\n\nconst Correction = function(props) {\n  var userAnswer = props.userAnswer;\n\n  if(userAnswer.score == 1) {\n    return <div className=\"alert alert-success\">{window.I18N.correct_answer}!</div>;\n\n  } else if(userAnswer.score == 0) {\n    return <div className=\"alert alert-danger\">\n      {window.I18N.wrong_answer}!&nbsp;\n      {userAnswer.value\n        ? <span>{window.I18N.your_answer_was}: <strong><Value content={userAnswer.value} type={userAnswer.kind} single=\"1\" /></strong></span>\n        : <span>{window.I18N.your_answer_was_empty}</span>}\n    </div>;\n\n  } else {\n    return <div className=\"alert alert-warning\">\n      {window.I18N.near_answer}!&nbsp;\n      <span>{window.I18N.your_answer_was}: <strong>\n        {userAnswer.kind == 'text'\n          ? <span>{userAnswer.testValue} <small\n              className=\"correction\"\n              dangerouslySetInnerHTML={{__html: '(' + highlightDiff(userAnswer.testValue, userAnswer.refValue) + ')'}}\n            /></span>\n          : <Value content={userAnswer.value} type={userAnswer.kind} single=\"1\" />}\n      </strong></span>\n    </div>;\n  }\n};\n\nconst Presentation = function(props){\n  var item = props.item,\n      userAnswer = props.userAnswer,\n      k    = Date.now(),\n      i    = 0,\n      item_lang = '';\n\n  // Add TSS if we're learning a language\n  if (this.props.langCodeTarget && this.props.langCodeSource) {\n    item_lang = item.item.direction == 'target' ? this.props.langCodeTarget : this.props.langCodeSource;\n  }\n\treturn <div>\n\n    {/*-- Correction --*/}\n    {userAnswer && <Correction userAnswer={userAnswer} />}\n\n    {/*-- Content --*/}\n    <table className=\"learn nicebox big thing autoplay\">\n\n        {/*-- Item --*/}\n        <tr>\n          <td className=\"label\">{item.item.label}</td>\n          <td className=\"item\">\n            <Value content={item.item.value} type={item.item.kind} lang={item_lang} className={item.audio ? '' : 'tts'} />\n            {item.item.alternatives.map(txt =>\n              <div key={k + i++} className=\"alt\">{txt}</div>\n            )}\n          </td>\n        </tr>\n\n        {/*-- Definition --*/}\n        <tr>\n          <td className=\"label\">{item.definition.label}</td>\n          <td className=\"definition\">\n            <Value content={item.definition.value} type={item.definition.kind} />\n            {item.definition.alternatives.map(txt =>\n              <div key={k + i++} className=\"alt\">{txt}</div>\n            )}\n          </td>\n        </tr>\n        <tr className=\"sep\"><td colSpan=\"2\"></td></tr>\n\n        {/*-- Audio --*/}\n        {!this.props.disableMultimedia && item.audio && <tr key={k + i++}>\n          <td className=\"label\">{item.audio.label}</td>\n          <td className=\"audio\"><Value content={item.audio.value} type=\"audio\" /></td>\n        </tr>}\n\n        {/*-- Additional content --*/}\n        {item.visible_info.map(it => <tr key={k + i++}>\n          <td className=\"label\">{it.label}</td>\n          <td className=\"more\"><Value content={it.value} type={it.kind} /></td>\n        </tr>)}\n\n        {item.hidden_info.map(it => <tr key={k + i++}>\n          <td className=\"label\">{it.label}</td>\n          <td className=\"more\"><Value content={it.value} type={it.kind} /></td>\n        </tr>)}\n\n        {/*-- Attributs --*/}\n        {item.attributes.map(it => <tr key={k + i++}>\n          <td className=\"label\">{it.label}</td>\n          <td className=\"more\"><span className=\"badge\"><Value content={it.value} type=\"text\" single=\"1\" /></span></td>\n        </tr>)}\n      </table>\n\n      {/*-- Copytyping --*/}\n      {props.prompt && <div className=\"typing-container\" key={k + i++}>\n          <div className=\"typing\">\n            <input\n              type=\"text\"\n              autoComplete=\"off\"\n              spellCheck=\"false\"\n              value=\"\"\n              placeholder={props.prompt.answer.value}\n              tabIndex=\"1\"\n              autoFocus=\"autofocus\"\n            />\n            <ul className=\"keyboard\">{props.prompt.choices.map((letter, i) =>\n              <li key={i} className=\"button\" tabIndex=\"0\">{letter}</li>\n            )}</ul>\n          </div>\n        </div>}\n    </div>;\n};\n\nfunction getPromptType(prompt) {\n  if(prompt.text) return 'text';\n  if(prompt.image) return 'image';\n  if(prompt.audio) return 'audio';\n  if(prompt.video) return 'video';\n}\n\nvar RandomGenerator = {\n  it: {},\n\n  newIterator: function(n) {\n    return randomize(Array.from({length: n}).map((x, i) => i)).values();\n  },\n\n  getIterator: function(n) {\n    if (!(n in RandomGenerator.it)) {\n      RandomGenerator.it[n.toString()] = RandomGenerator.newIterator(n);\n    }\n    return RandomGenerator.it[n.toString()];\n  },\n\n  setNextScreenRand: function(n) {\n    var it = RandomGenerator.getIterator(n);\n    var rnd = it.next();\n\n    if (rnd.done) {\n      it = RandomGenerator.it[n.toString()] = RandomGenerator.newIterator(n);\n      rnd = it.next();\n    }\n    return rnd.value;\n  },\n};\n\nconst MultipleChoice = function(props) {\n  var item       = props.item,\n      itemType   = props.promptWith || getPromptType(item.prompt),\n      answerType = item.answer.kind;\n\n  // Randomize choices order\n  var n          = item.choices.length,\n      choicesRnd = randomize([...item.choices]);\n\n  // Display 9 choices max\n  if(n > props.nChoices) {\n    choicesRnd = choicesRnd.slice(0, props.nChoices);\n    n = choicesRnd.length;\n\n  } else if(n < props.nChoices) {\n    for (let i=n; i<props.nChoices; i++) {\n      choicesRnd.push(choicesRnd.random());\n    }\n  }\n\n  // Place the right answer somewhere in it\n  var rnd  = n == 4 ? RandomGenerator.setNextScreenRand(4) : randrange(0, n - 1),\n     isArr = $.isArray(item.answer.value);\n\n  if(isArr) {\n    var choice = item.answer.value.random();\n    choicesRnd[rnd] = choice.normal || choice.trim();\n  } else {\n    choicesRnd[rnd] = item.answer.value.trim();\n  }\n\n  // Get the list of answers that are acceptable\n  var rightAnswers = [];\n  if(isArr) {\n    for(var i=0; i<item.answer.value.length; i++) {\n      choice = item.answer.value[i];\n      rightAnswers.push(choice.normal || choice.trim());\n    }\n  } else {\n    choicesRnd[rnd] = item.answer.value.trim();\n    rightAnswers.push(item.answer.value.trim());\n  }\n  rightAnswers.push(item.answer.alternatives.map((value) => value.trim()));\n\n  // Display our screens\n  var choices = choicesRnd.map((value, i) => {\n    return (\n      <ChoiceBox\n        key={i}\n        i={i+1}\n        id={item.learnableID}\n        value={value}\n        answerType={answerType}\n        isValid={rightAnswers.includes(value)}\n      />\n    );\n  });\n  props.setChoices(choices, 'accesskey');\n\n  return <div className=\"nicebox\">\n\n    {/*-- Item --*/}\n    <div className=\"big choice autoplay\">\n      <Value content={item.prompt[itemType].value} type={itemType} />\n    </div>\n\n    {/*-- Choices --*/}\n    <div className={'medium choices n' + props.nChoices}>{choices}</div>\n  </div>;\n};\n\nconst ChoiceBox = function(props) {\n  return <div className={'choice-box nicebox ' + props.answerType}>\n    <input\n      type=\"radio\"\n      name={'learn-' + props.id}\n      id={'choice-' + props.i}\n      tabIndex=\"0\"\n      accessKey={props.i}\n      checked={false}\n      autoComplete={false}\n      className=\"radio\"\n    />\n    <span className=\"choice-index\">{props.i}.</span>\n    <Value content={props.value} type={props.answerType} single=\"1\" />\n  </div>;\n}\n\nconst Typing = function(props) {\n  var item     = props.item,\n      itemType = props.promptWith || getPromptType(item.prompt),\n      i = 0;\n\n  props.setChoices(item.correct, 'text', item.is_strict);\n\n  return <div className=\"nicebox\">\n    <div className=\"big choice autoplay\">\n      <Value content={item.prompt[itemType].value} type={itemType} />\n\n      {/*-- Attributs --*/}\n      {item.attributes && <div className=\"clues\">\n        {item.attributes.map(it => <span key={i++} className=\"badge\"><Value content={it.value} type=\"text\" single=\"1\" /></span>)}\n      </div>}\n    </div>\n    <div className=\"typing-container\">\n      <div className=\"typing\" key={Date.now()}>\n        <input type=\"text\" autoComplete=\"off\" spellCheck=\"false\" value=\"\" tabIndex=\"1\" autoFocus=\"autofocus\" />\n        <ul className=\"keyboard\">{item.choices.map((letter, i) =>\n          <li key={letter} className=\"button\" tabIndex=\"0\">{letter}</li>\n        )}</ul>\n      </div>\n    </div>\n  </div>;\n};\n\nconst Tapping = function(props) {\n  var item     = props.item,\n      itemType = getPromptType(item.prompt);\n\n  props.setChoices(item.correct, 'tapping', item.is_strict);\n\n  var n       = item.correct.length,\n      choices = item.correct[0].slice(),\n      remains = item.choices.filter((it) => !choices.includes(it)),\n      extra   = 0;\n\n  if(props.difficulty == 0) {\n    extra = 0;\n  } else if(n < 5){\n    extra = 6 - n;\n  } else {\n    extra = Math.min(Math.max(0, 15 - n), Math.ceil(props.difficulty * n));\n  }\n\n  for(var i=0; i<extra; i++) {\n    if(!remains.length) {\n      break;\n    }\n    var rnd = randrange(0, remains.length - 1),\n        it  = remains.splice(rnd, 1);\n    choices.push(...it);\n  }\n  i = 0;\n\n  return <div className=\"nicebox\">\n    <div className=\"big choice autoplay\">\n      <Value content={item.prompt[itemType].value} type={itemType} />\n\n      {/*-- Attributs --*/}\n      {item.attributes && <div className=\"clues\">\n        {item.attributes.map(it => <span key={i++} className=\"badge\"><Value content={it.value} type=\"text\" single=\"1\" /></span>)}\n      </div>}\n    </div>\n    <div className=\"tapping-container\">\n      <div className=\"tapping\" key={Date.now()}>\n        <div className=\"input\"></div>\n        <ul className=\"keyboard\">{randomize(choices).map((word, i) =>\n          <li key={i} className=\"button\" tabIndex=\"0\" id={'btn-' + i}>{word}</li>\n        )}</ul>\n      </div>\n    </div>\n  </div>;\n};\n\nconst Summary = function(props) {\n  var items = props.items,\n      session_type = props.session_type,\n      i = 0;\n\n  return <table className=\"learn nicebox summary\">\n  {items.map((item) => {\n    var rate = '';\n\n    // Compute success rate\n    if(session_type != 'preview') {\n      var successRate = item.right / item.count * 100,\n          className = (\n            successRate == 100 ? 'neverMissed' : (\n              successRate < 20 ? 'oftenMissed' : (\n                successRate > 80 ? 'rarelyMissed' : 'sometimesMissed'\n          ))),\n          rate = <span className={className}>{item.right}/{item.count}</span>;\n    }\n\n    // Render item\n    return <tr key={i++} className=\"thing\">\n      <td><Value content={item.item.value} type={item.item.kind} /></td>\n      <td><Value content={item.definition.value} type={item.definition.kind} /></td>\n      {rate && <td>{rate}</td>}\n    </tr>})}\n  </table>;\n};\n\n//+--------------------------------------------------------\n//| SCORING SYSTEM\n//+--------------------------------------------------------\n\nconst AwardPoints = {\n  getPoints(session_type, template, time_spent, score, current_streak) {\n    var points      = 0,\n        speed_bonus = 0;\n\n    // Score\n    switch(session_type){\n      case 'learn':\n        points = AwardPoints.getPoints_learn(score);\n        break;\n\n      case 'classic_review':\n        points = AwardPoints.getPoints_learn(score);\n        if(current_streak) {\n          points = AwardPoints.getPoints_review(points, current_streak);\n        }\n        if(score == 1 && time_spent) {\n          // computePoints_bonusForAccuracy(nb_scheduled_correct / nb_scheduled * 100, nb_scheduled);\n          speed_bonus = AwardPoints.getPoints_bonusForSpeed(time_spent, template);\n        }\n        break;\n\n      case 'speed_review':\n        if(score == 1) {\n          points = AwardPoints.getPoints_speedReview(time_spent);\n        }\n        break;\n    }\n    return points + speed_bonus;\n  },\n\n  getPoints_learn: function(score) {\n    return 1 === score ? 45 : 0 === score ? 0 : Math.max(10, Math.round(45 * score) - 20);\n  },\n  getPoints_speedReview: function(time_spent) {\n    var t = Math.floor(time_spent / 1e3);\n    return t >= 6 ? Math.min(15, 25) : Math.min(15 + 7 * (6 - t), 25);\n  },\n  getPoints_review: function(points, current_streak) {\n    points *= Math.pow(1.2, current_streak);\n    points  = Math.min(points, 150);\n    return Math.ceil(points);\n  },\n  getPoints_bonusForSpeed: function(time_spent, tpl) {\n    if(tpl == 'typing') {\n      return time_spent < 4e3 ? 5 : 0;\n    } else {\n      return time_spent < 2e3 ? 3 : 0;\n    }\n  },\n  getPoints_bonusForAccuracy: function(percent_correct, nb_scheduled_correct) {\n    if(percent_correct == 100) {\n      return 20 * nb_scheduled_correct;\n\n    } else if(percent_correct >= 90) {\n      return 12 * nb_scheduled_correct;\n\n    } else if(percent_correct >= 80) {\n      return 6 * nb_scheduled_correct;\n\n    } else if(percent_correct >= 70) {\n      return 4 * nb_scheduled_correct;\n\n    } else if(percent_correct >= 50) {\n      return 2 * nb_scheduled_correct;\n\n    } else {\n      return 0;\n    }\n  }\n};\n\nconst ScoreAnswer = {\n  FIRST_LETTER_WEIGHT: .1,\n  DISTANCE_WEIGHT: .9,\n\n  /**\n   * Check whether the givenAnswer is right or not\n   * And score the similarity between the given response and the expected answer\n   * (1 = correct, 0 = incorrect, 0<x<1 = more or less similar)\n   */\n  computeScore: function(givenAnswer, rightAnswer) {\n    if(!givenAnswer) {\n      return 0;\n    }\n    var both_are_numeric = $.isNumeric(parseInt(givenAnswer, 10)) && $.isNumeric(parseInt(rightAnswer, 10));\n\n    if(both_are_numeric) {\n      return ScoreAnswer.getNumericScore(givenAnswer, rightAnswer);\n    } else {\n      return ScoreAnswer.getStringScore(givenAnswer, rightAnswer);\n    }\n  },\n\n  getNumericScore: function(givenAnswer, rightAnswer) {\n    return (parseInt(givenAnswer, 10) === parseInt(rightAnswer, 10) ? 1 : 0);\n  },\n\n  getStringScore: function(givenAnswer, rightAnswer) {\n    var tolerance = ScoreAnswer.getDistanceTolerance(rightAnswer.length),\n        distance = ScoreAnswer.getStringDistance(givenAnswer, rightAnswer);\n    if (distance >= tolerance) return 0;\n\n    var weightFirstLetter = rightAnswer.charAt(0) === givenAnswer.charAt(0) ? 1 : 0,\n        weight = (tolerance - distance) / tolerance,\n        s = ScoreAnswer.FIRST_LETTER_WEIGHT * weightFirstLetter + ScoreAnswer.DISTANCE_WEIGHT * weight;\n\n    return s < .5 && (s = 0), s;\n  },\n\n  getDistanceTolerance: function(length) {\n    return length * (\n      length > 18 ? .5\n        : length < 3 ? 1\n          : -1 * length / 33 + 1.1\n    );\n  },\n\n  /**\n   * Compute the levenshtein distance between a and b\n   */\n  getStringDistance: function(a, b) {\n    var computeDistanceMatrix = function() {\n      var getItemAt;\n\n      if($.isArray(a)) {\n        getItemAt = function(arr, i) { return arr[i] };\n      } else {\n        getItemAt = function(arr, i) { return arr.charAt(i) };\n      }\n\n      // Create matrix\n      var matrix = [];\n      for (var i = 0; i <= a.length; i += 1) matrix[i] = [], matrix[i][0] = i;\n      for (var j = 0; j <= b.length; j += 1) matrix[0][j] = j;\n\n      // Calculate distance\n      for (var i = 1; i <= a.length; i += 1) {\n        for (var j = 1; j <= b.length; j += 1) {\n          matrix[i][j] = Math.min(\n            matrix[i - 1][j] + 1,\n            matrix[i][j - 1] + 1,\n            matrix[i - 1][j - 1] + (getItemAt(a, i - 1) === getItemAt(b, j - 1) ? 0 : 1)\n          );\n        }\n      }\n      return matrix;\n    };\n\n    var matrix = computeDistanceMatrix();\n    return matrix[a.length][b.length];\n  }\n}\n\n//+--------------------------------------------------------\n//| TEXT NORMALIZATION\n//+--------------------------------------------------------\n\n// https://cdnjs.cloudflare.com/ajax/libs/xregexp/3.1.1/xregexp-all.js\nconst RegexUnicode = {\n  'C': '\\0-\\x1F\\x7F-\\x9F\\xAD\\u0378\\u0379\\u0380-\\u0383\\u038B\\u038D\\u03A2\\u0530\\u0557\\u0558\\u0560\\u0588\\u058B\\u058C\\u0590\\u05C8-\\u05CF\\u05EB-\\u05EF\\u05F5-\\u0605\\u061C\\u061D\\u06DD\\u070E\\u070F\\u074B\\u074C\\u07B2-\\u07BF\\u07FB-\\u07FF\\u082E\\u082F\\u083F\\u085C\\u085D\\u085F-\\u089F\\u08B5-\\u08E2\\u0984\\u098D\\u098E\\u0991\\u0992\\u09A9\\u09B1\\u09B3-\\u09B5\\u09BA\\u09BB\\u09C5\\u09C6\\u09C9\\u09CA\\u09CF-\\u09D6\\u09D8-\\u09DB\\u09DE\\u09E4\\u09E5\\u09FC-\\u0A00\\u0A04\\u0A0B-\\u0A0E\\u0A11\\u0A12\\u0A29\\u0A31\\u0A34\\u0A37\\u0A3A\\u0A3B\\u0A3D\\u0A43-\\u0A46\\u0A49\\u0A4A\\u0A4E-\\u0A50\\u0A52-\\u0A58\\u0A5D\\u0A5F-\\u0A65\\u0A76-\\u0A80\\u0A84\\u0A8E\\u0A92\\u0AA9\\u0AB1\\u0AB4\\u0ABA\\u0ABB\\u0AC6\\u0ACA\\u0ACE\\u0ACF\\u0AD1-\\u0ADF\\u0AE4\\u0AE5\\u0AF2-\\u0AF8\\u0AFA-\\u0B00\\u0B04\\u0B0D\\u0B0E\\u0B11\\u0B12\\u0B29\\u0B31\\u0B34\\u0B3A\\u0B3B\\u0B45\\u0B46\\u0B49\\u0B4A\\u0B4E-\\u0B55\\u0B58-\\u0B5B\\u0B5E\\u0B64\\u0B65\\u0B78-\\u0B81\\u0B84\\u0B8B-\\u0B8D\\u0B91\\u0B96-\\u0B98\\u0B9B\\u0B9D\\u0BA0-\\u0BA2\\u0BA5-\\u0BA7\\u0BAB-\\u0BAD\\u0BBA-\\u0BBD\\u0BC3-\\u0BC5\\u0BC9\\u0BCE\\u0BCF\\u0BD1-\\u0BD6\\u0BD8-\\u0BE5\\u0BFB-\\u0BFF\\u0C04\\u0C0D\\u0C11\\u0C29\\u0C3A-\\u0C3C\\u0C45\\u0C49\\u0C4E-\\u0C54\\u0C57\\u0C5B-\\u0C5F\\u0C64\\u0C65\\u0C70-\\u0C77\\u0C80\\u0C84\\u0C8D\\u0C91\\u0CA9\\u0CB4\\u0C